-- V288: a distinct 150-knowledge namespace; V284–286 ownership and learned effects survive unchanged.
create table ludus_staff_private.papyrus_catalog_v288 (
 content_id text primary key,role_id text not null references ludus_staff_private.roles_v284(id),
 profession text not null,ordinal smallint not null check(ordinal between 1 and 25),
 title text not null,subtitle text not null,paragraph text not null,effect_text text not null,
 rarity text not null check(rarity in('common','rare','very_rare','unique')),
 runtime_status text not null default 'pending_feature' check(runtime_status in('active','pending_feature')),
 runtime_reason text default 'Bu bilginin ilgili oyun koşulu henüz hazır değil.',runtime_note text,
 effect jsonb not null check(jsonb_typeof(effect)='object'),conditions jsonb not null check(jsonb_typeof(conditions)='array'),
 unique(role_id,ordinal)
);
create table ludus_staff_private.holdings_v288 (
 owner_id uuid references public.ludus_accounts(user_id) on delete cascade,
 content_id text references ludus_staff_private.papyrus_catalog_v288(content_id),
 quantity integer not null check(quantity>=0),received_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,content_id)
);
create table ludus_staff_private.knowledge_v288 (
 owner_id uuid references public.ludus_accounts(user_id) on delete cascade,
 content_id text references ludus_staff_private.papyrus_catalog_v288(content_id),
 learned_at timestamptz not null default clock_timestamp(),primary key(owner_id,content_id)
);
-- Deliberately no account FK: account deletion or consumption never resets mint supply.
create table ludus_staff_private.unique_mints_v288 (
 content_id text primary key references ludus_staff_private.papyrus_catalog_v288(content_id),
 first_owner_id uuid not null,finder_ludus text not null,found_at timestamptz not null default clock_timestamp(),source_key text not null
);
create table ludus_staff_private.read_receipts_v288 (
 owner_id uuid references public.ludus_accounts(user_id) on delete cascade,request_id uuid,
 content_id text not null references ludus_staff_private.papyrus_catalog_v288(content_id),
 created_at timestamptz not null default clock_timestamp(),primary key(owner_id,request_id)
);
create table ludus_staff_private.grant_requests_v288 (
 request_id uuid primary key,owner_id uuid not null,expected_username text not null,expected_ludus_name text not null,
 planned_ids jsonb not null check(jsonb_typeof(planned_ids)='array' and jsonb_array_length(planned_ids)=90),
 receipt jsonb,applied_at timestamptz
);
create table ludus_staff_private.loot_settings_v288 (
 singleton boolean primary key default true check(singleton),all_matches boolean not null default true,
 allowed_match_types text[] not null default '{}'
);
insert into ludus_staff_private.loot_settings_v288(singleton)values(true);
-- Explicit deny list for test accounts; never infer it from mutable profile metadata.
create table ludus_staff_private.loot_exclusions_v288(owner_id uuid primary key,reason text not null);
insert into ludus_staff_private.papyrus_catalog_v288(content_id,role_id,profession,ordinal,title,subtitle,paragraph,effect_text,rarity,effect,conditions) select * from jsonb_to_recordset($catalog$[{"content_id":"doctor_001","role_id":"doctor","profession":"doctor","ordinal":1,"title":"Sargı Bağlama Sanatı","subtitle":"Yaranın ihtiyacını anlayarak malzemeyi yerinde kullanmayı öğrenmek.","paragraph":"Papirüs, farklı yara biçimleri için tutulmuş sargı çizimlerini ve bir hekimin bu çizimlere düştüğü notları içerir. Doktor, her yaranın ne kadar sargı gerektirdiğini değerlendirmeyi öğrenir. Bu ustalık sayesinde en az iki sargı isteyen tedavilerde **%0,4 ihtimalle bir sargı kasada kalır**.","effect_text":"%0,4 ihtimalle bir sargı kasada kalır","rarity":"common","effect":{"metric":"sargi","operation":"event_probability","value":0.004,"unit":"fraction"},"conditions":["En az iki sargı gerektiren tedavi","Bir adet korunur"]},{"content_id":"doctor_002","role_id":"doctor","profession":"doctor","ordinal":2,"title":"Atelle Destekleme Bilgisi","subtitle":"Ahşabı yaralının ihtiyacına göre değerlendirebilmek.","paragraph":"Çizimlerin yanında, aynı atel malzemesinin farklı vakalarda nasıl değerlendirildiğini anlatan açıklamalar bulunur. Doktor bu bilgiden yararlanarak atel kullanımını daha iyi planlamayı öğrenir. Atel gerektiren tedavilerde **%0,2 ihtimalle bir atel kasada kalır**.","effect_text":"%0,2 ihtimalle bir atel kasada kalır","rarity":"common","effect":{"metric":"atel","operation":"event_probability","value":0.002,"unit":"fraction"},"conditions":["Atel gerektiren tedavi","Bir adet korunur"]},{"content_id":"doctor_003","role_id":"doctor","profession":"doctor","ordinal":3,"title":"Yara Yüzeyini Okumak","subtitle":"Bakımın nereden başlayacağını gözlemle belirleyebilmek.","paragraph":"Birbirine benzeyen yaraların yanına yazılmış farklı gözlemler, Doktora bakım ihtiyacını ayırt etmeyi öğretir. Bu bilgiyi öğrenen Doktor, Sirkeli Sünger kullanımını daha dikkatli planlar. İlgili tedavide **%0,2 ihtimalle bir Sirkeli Sünger kasada kalır**.","effect_text":"%0,2 ihtimalle bir Sirkeli Sünger kasada kalır","rarity":"common","effect":{"metric":"sirkeli_sunger","operation":"event_probability","value":0.002,"unit":"fraction"},"conditions":["Sirkeli Sünger kullanılan tedavi","Bir adet korunur"]},{"content_id":"doctor_004","role_id":"doctor","profession":"doctor","ordinal":4,"title":"Balmumu Merhemi Üzerine","subtitle":"Bir karışımı tanıyarak kullanımında ustalaşmak.","paragraph":"Papirüsteki vaka notları, balmumu merheminin bakım sırasında nasıl değerlendirildiğini anlatır. Doktor, yaranın ihtiyacıyla kullanılacak miktar arasındaki ilişkiyi öğrenir. Balmumu Merhemi kullanılan tedavilerde **%0,2 ihtimalle bir doz kasada kalır**.","effect_text":"%0,2 ihtimalle bir doz kasada kalır","rarity":"common","effect":{"metric":"balmumu_merhemi","operation":"event_probability","value":0.002,"unit":"fraction"},"conditions":["Balmumu Merhemi kullanılan tedavi","Bir doz korunur"]},{"content_id":"doctor_005","role_id":"doctor","profession":"doctor","ordinal":5,"title":"Defne Merheminin Ölçüsü","subtitle":"Bakımın gerektirdiği miktarı deneyimden öğrenmek.","paragraph":"Ezilme ve zorlanma vakalarının yanına düşülen notlar, Doktorun merhem kullanımına ilişkin bilgisini derinleştirir. Öğrendiği ölçülü kullanım, revirin eldeki malzemeden daha iyi yararlanmasını sağlar. Defne Merhemi kullanılan tedavilerde **%0,2 ihtimalle bir doz kasada kalır**.","effect_text":"%0,2 ihtimalle bir doz kasada kalır","rarity":"common","effect":{"metric":"defne_merhemi","operation":"event_probability","value":0.002,"unit":"fraction"},"conditions":["Defne Merhemi kullanılan tedavi","Bir doz korunur"]},{"content_id":"doctor_006","role_id":"doctor","profession":"doctor","ordinal":6,"title":"İstirahatte Şurupla Bakım","subtitle":"Dinlenme sırasında verilen desteği daha iyi değerlendirmek.","paragraph":"Papirüs, Ballı Sirke Şurubu verilen yaralıların dinlenme kayıtlarını bir araya getirir. Doktor, bakım ile dinlenmeyi birlikte değerlendirmeyi öğrenir. Bu öğrenimin pasif etkisiyle şurubun revirde sağladığı **ek yorgunluk giderimi %0,4 artar**.","effect_text":"ek yorgunluk giderimi %0,4 artar","rarity":"common","effect":{"metric":"balli_sirke_syrup_additional_fatigue_recovery","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Revirde Ballı Sirke Şurubunun ek yorgunluk giderimi"]},{"content_id":"doctor_007","role_id":"doctor","profession":"doctor","ordinal":7,"title":"Dönüş Gününün Hazırlığı","subtitle":"Tedavinin ardından kalan yorgunluğu değerlendirebilmek.","paragraph":"Bir hekimin taburculuk gözlemleri, Doktora iyileşen gladyatörün geri dönüşe ne kadar hazır olduğunu okumayı öğretir. İncir Şurubunun bu aşamadaki kullanımına ilişkin bilgi kazanır. Şurubun taburculukta giderdiği **yorgunluk miktarı %0,4 artar**.","effect_text":"yorgunluk miktarı %0,4 artar","rarity":"common","effect":{"metric":"incir_syrup_discharge_fatigue_recovery","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Taburculukta İncir Şurubu kullanımı"]},{"content_id":"doctor_008","role_id":"doctor","profession":"doctor","ordinal":8,"title":"Kısa İstirahatin Düzeni","subtitle":"Birkaç saatlik bakımı bilinçli yönetmeyi öğrenmek.","paragraph":"Papirüs, hafif yaralanmaların ardından uygulanan dinlenme düzenine ilişkin gözlemler taşır. Doktor, kısa revir süresini gladyatörün toparlanmasını destekleyecek şekilde değerlendirmeyi öğrenir. Hafif sakatlığın **3 saatlik revir süresinde yorgunluk %0,2 daha hızlı azalır**.","effect_text":"3 saatlik revir süresinde yorgunluk %0,2 daha hızlı azalır","rarity":"common","effect":{"metric":"fatigue_recovery_rate","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":["Hafif sakatlık","3 saatlik revir süreci"]},{"content_id":"doctor_009","role_id":"doctor","profession":"doctor","ordinal":9,"title":"Gece Gözetiminin Esasları","subtitle":"Uzun dinlenme boyunca bakımın devamlılığını sağlayabilmek.","paragraph":"Gece nöbetlerinde tutulan kayıtlar, yaralının durumunun zaman içinde nasıl takip edildiğini anlatır. Doktor, dinlenmenin farklı aşamalarında bakım düzenini sürdürme becerisi kazanır. Orta sakatlığın **12 saatlik revir süresinde yorgunluk %0,4 daha hızlı azalır**.","effect_text":"12 saatlik revir süresinde yorgunluk %0,4 daha hızlı azalır","rarity":"common","effect":{"metric":"fatigue_recovery_rate","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Orta sakatlık","12 saatlik revir süreci"]},{"content_id":"doctor_010","role_id":"doctor","profession":"doctor","ordinal":10,"title":"Ağır Yaralının Gözetimi","subtitle":"Uzun süren bakımda dikkatini ve düzenini koruyabilmek.","paragraph":"Ağır yaralılar için tutulmuş ayrıntılı kayıtlar, Doktora bir günlük bakımın nasıl planlandığını öğretir. Her gözlemi bir öncekiyle ilişkilendirerek hastanın dinlenmesini daha iyi desteklemeyi öğrenir. Kötü sakatlığın **24 saatlik revir süresinde yorgunluk %0,4 daha hızlı azalır**.","effect_text":"24 saatlik revir süresinde yorgunluk %0,4 daha hızlı azalır","rarity":"rare","effect":{"metric":"fatigue_recovery_rate","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Kötü sakatlık","24 saatlik revir süreci"]},{"content_id":"doctor_011","role_id":"doctor","profession":"doctor","ordinal":11,"title":"Zırhın Bedende Bıraktığı İzler","subtitle":"Ekipmanla beden arasındaki uyumsuzluğu fark edebilmek.","paragraph":"Papirüste, omuz üzerindeki sürtünme izleriyle farklı zırhların oturuşunu karşılaştıran çizimler bulunur. Doktor bu çizimleri okuyarak maç öncesi kontrolde nelere dikkat edeceğini öğrenir. Ludusun gladyatörlerinde **omuzda zırh vurması ihtimali %0,4 azalır**.","effect_text":"omuzda zırh vurması ihtimali %0,4 azalır","rarity":"common","effect":{"metric":"shoulder_chafing_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kendi ludusunun gladyatörleri"]},{"content_id":"doctor_012","role_id":"doctor","profession":"doctor","ordinal":12,"title":"Kasın Sınırını Tanımak","subtitle":"Zorlanmanın belirtilerini hazırlık sırasında okuyabilmek.","paragraph":"Yorulan bacaklar üzerine tutulmuş gözlemler, Doktora baldırın zorlanmaya açık olduğu durumları değerlendirmeyi öğretir. Bu bilgi gladyatörlerin maç öncesi bakımına yansır. Ludusun gladyatörlerinde **hafif baldır zorlanması ihtimali %0,4 azalır**.","effect_text":"hafif baldır zorlanması ihtimali %0,4 azalır","rarity":"common","effect":{"metric":"mild_calf_strain_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kendi ludusunun gladyatörleri"]},{"content_id":"doctor_013","role_id":"doctor","profession":"doctor","ordinal":13,"title":"Ayak Bileğinin Dengesi","subtitle":"Hareketin taşıdığı yükü ve destek ihtiyacını anlayabilmek.","paragraph":"Dönüş, duruş ve ani yön değiştirme çizimleri, ayak bileğinin farklı hareketlerde üstlendiği yükü anlatır. Doktor bu bilgiyi öğrenerek gladyatörün maça hazırlanmasına daha bilinçli katkıda bulunur. **Ayak bileği burkulması ihtimali %0,4 azalır**.","effect_text":"Ayak bileği burkulması ihtimali %0,4 azalır","rarity":"rare","effect":{"metric":"ankle_sprain_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kendi ludusunun gladyatörleri"]},{"content_id":"doctor_014","role_id":"doctor","profession":"doctor","ordinal":14,"title":"İyileşen Kemiğin Korunması","subtitle":"Geçmiş sakatlığın bilgisini geri dönüş hazırlığında kullanmak.","paragraph":"Papirüs, kırık geçirmiş gladyatörlerin arenaya dönüşüne ait gözlemleri içerir. Doktor, yaralanma geçmişini ilk maçın hazırlığına nasıl taşıyacağını öğrenir. Kırıktan dönen gladyatörün **ilk maçında aynı kemiğin yeniden kırılma ihtimali %0,4 azalır**.","effect_text":"ilk maçında aynı kemiğin yeniden kırılma ihtimali %0,4 azalır","rarity":"rare","effect":{"metric":"same_bone_refracture_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kırık sonrası ilk maç","Aynı kemik"]},{"content_id":"doctor_015","role_id":"doctor","profession":"doctor","ordinal":15,"title":"Baş Darbesinin Ardından","subtitle":"Eski bir yaralanmayı sonraki hazırlıkta hatırlamak.","paragraph":"Başından ağır yaralanmış gladyatörlerin dönüş kayıtları, Doktora takip bilgisinin değerini gösterir. Öğrendiği gözlem yöntemiyle ilk maç öncesi koruyucu hazırlığa daha fazla dikkat eder. Ağır kafa travmasından dönen gladyatörün **ilk maçında aynı sakatlığı tekrar geçirme ihtimali %0,4 azalır**.","effect_text":"ilk maçında aynı sakatlığı tekrar geçirme ihtimali %0,4 azalır","rarity":"very_rare","effect":{"metric":"repeat_severe_head_trauma_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Ağır kafa travması sonrası ilk maç","Aynı sakatlık"]},{"content_id":"doctor_016","role_id":"doctor","profession":"doctor","ordinal":16,"title":"Düşmenin Bedendeki İzleri","subtitle":"Yere temasın oluşturduğu yaralanmaları tanıyabilmek.","paragraph":"Papirüsteki çizimler, farklı düşüşlerin diz üzerinde bıraktığı izleri karşılaştırır. Doktor bu bilgiden yararlanarak gladyatörlerin düşmeye bağlı yaralanmalara karşı hazırlığını geliştirir. Maçta yere düşen gladyatörün **diz sıyrığı yaşama ihtimali %0,4 azalır**.","effect_text":"diz sıyrığı yaşama ihtimali %0,4 azalır","rarity":"common","effect":{"metric":"knee_abrasion_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Maçta yere düşme"]},{"content_id":"doctor_017","role_id":"doctor","profession":"doctor","ordinal":17,"title":"Yüz Yaralarına Karşı Hazırlık","subtitle":"Yüzün açıkta kalan bölgelerini değerlendirebilmek.","paragraph":"Yüz yaralarına ilişkin kayıtlar, Doktora başın korunmasında dikkat gerektiren bölgeleri öğretir. Bu bilgiyi öğrenmesi, maç öncesi yüz korumasını değerlendirme becerisine yansır. Kaş yarılmasıyla sonuçlanabilecek bir baş darbesinde **bu sakatlığın ihtimali %0,4 azalır**.","effect_text":"bu sakatlığın ihtimali %0,4 azalır","rarity":"rare","effect":{"metric":"eyebrow_laceration_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kaş yarılmasıyla sonuçlanabilecek baş darbesi"]},{"content_id":"doctor_018","role_id":"doctor","profession":"doctor","ordinal":18,"title":"Omuzun Hareketi ve Korunması","subtitle":"Hareket eden bir eklemin koruma ihtiyacını okuyabilmek.","paragraph":"Kalkan taşıyan ve silah savuran kolların çizimleri, omuzun farklı duruşlarda nasıl açıkta kaldığını anlatır. Doktor, koruyucu hazırlığı hareketle birlikte değerlendirmeyi öğrenir. Omuza alınan darbede **omuz ezilmesi ihtimali %0,4 azalır**.","effect_text":"omuz ezilmesi ihtimali %0,4 azalır","rarity":"rare","effect":{"metric":"shoulder_contusion_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Omuza alınan darbe"]},{"content_id":"doctor_019","role_id":"doctor","profession":"doctor","ordinal":19,"title":"Derin Kesiklerde Sargı Düzeni","subtitle":"Zor bir vakada malzemeyi daha bilinçli kullanabilmek.","paragraph":"Derin ön kol kesiklerine ayrılan bu papirüs, genel sargı bilgisini tek bir yaralanma üzerinde derinleştirir. Doktor, tedavinin malzeme ihtiyacını daha iyi planlamayı öğrenir. Gereken iki sargıdan birini koruma şansı **%0,8 olur**. Sargı Bağlama Sanatı da öğrenilmişse bu yüksek oran uygulanır.","effect_text":"%0,8 olur","rarity":"rare","effect":{"metric":"sargi","operation":"event_probability","value":0.008,"unit":"fraction"},"conditions":["Derin ön kol kesiği","İki sargıdan biri korunur","doctor_001 ile yüksek oran uygulanır"]},{"content_id":"doctor_020","role_id":"doctor","profession":"doctor","ordinal":20,"title":"Göğüs Travmalarında İstirahat","subtitle":"Yaralanmanın yerine göre bakım bilgisini derinleştirmek.","paragraph":"Kaburga ezilmesi yaşayan gladyatörlere ait gözlemler, dinlenme desteğinin bu vakalarda nasıl değerlendirildiğini anlatır. Doktor, Ballı Sirke Şurubunun revirde kullanımında uzmanlaşır. Kaburga ezilmesinde şurubun sağladığı **ek yorgunluk giderimi %0,8 artar**.","effect_text":"ek yorgunluk giderimi %0,8 artar","rarity":"rare","effect":{"metric":"balli_sirke_syrup_additional_fatigue_recovery","operation":"relative_increase","value":0.008,"unit":"fraction"},"conditions":["Kaburga ezilmesi","Ballı Sirke Şurubu"]},{"content_id":"doctor_021","role_id":"doctor","profession":"doctor","ordinal":21,"title":"Ağır Kırıklardan Korunma","subtitle":"Bir darbenin ağırlığını artıran koşulları önceden tanımak.","paragraph":"Alt bacak yaralanmalarını karşılaştıran çizimler, Doktora maç öncesi koruyucu hazırlık konusunda ileri bilgi kazandırır. Bu bilginin oyun içi sonucu, sakatlık belirlenirken ortaya çıkar. Açık kaval kemiği kırığı çıkacaksa **%0,4 ihtimalle sonuç kapalı, parçalı olmayan kaval kemiği kırığı olur**.","effect_text":"%0,4 ihtimalle sonuç kapalı, parçalı olmayan kaval kemiği kırığı olur","rarity":"unique","effect":{"metric":"open_tibia_to_closed_unfragmented_tibia","operation":"event_probability","value":0.004,"unit":"fraction"},"conditions":["Maç sonunda sakatlık belirlenmesi","Açık kaval kemiği kırığı sonucu","Kapalı, parçalı olmayan kaval kemiği kırığına dönüşür"]},{"content_id":"doctor_022","role_id":"doctor","profession":"doctor","ordinal":22,"title":"Kalçanın Yük Taşıma Bilgisi","subtitle":"Düşüşün bedene aktardığı yükü anlayabilmek.","paragraph":"Papirüs, sert düşüşlerde kalça ve leğen bölgesinin maruz kaldığı yükü anlatan çizimler içerir. Doktor, bu bölgeyi korumaya yönelik hazırlığını gözlem bilgisiyle geliştirir. Sert düşüşlerde **leğen kemiği kırığı oluşma ihtimali %0,4 azalır**.","effect_text":"leğen kemiği kırığı oluşma ihtimali %0,4 azalır","rarity":"rare","effect":{"metric":"pelvic_fracture_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Sert düşüş"]},{"content_id":"doctor_023","role_id":"doctor","profession":"doctor","ordinal":23,"title":"Karın Bölgesinin Korunması","subtitle":"Gövde darbelerinin tehlikesini değerlendirebilmek.","paragraph":"Gövde yaralanmalarına ayrılmış kayıtlar, Doktora karın bölgesinin maç öncesi korunmasında hangi noktalara dikkat edeceğini öğretir. Bu bilgi gladyatörlerin koruyucu hazırlığına pasif olarak katkıda bulunur. Gövdeye alınan ağır darbelerde **iç kanamalı karın yaralanması ihtimali %0,4 azalır**.","effect_text":"iç kanamalı karın yaralanması ihtimali %0,4 azalır","rarity":"very_rare","effect":{"metric":"internal_abdominal_bleeding_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Gövdeye ağır darbe"]},{"content_id":"doctor_024","role_id":"doctor","profession":"doctor","ordinal":24,"title":"Ağır Yaralanmadan Sonra Dönüş","subtitle":"Yaralının bütün geçmişini birlikte değerlendirebilmek.","paragraph":"Papirüs, ağır sakatlıktan dönen gladyatörlerin bedenini bir bütün olarak değerlendirmeye ilişkin notlar taşır. Doktor, geri dönüş hazırlığında başka ağır yaralanmalara açık noktaları da gözetmeyi öğrenir. Kötü sakatlıktan dönen gladyatörün **ilk maçında farklı bir kötü sakatlık geçirme ihtimali %0,4 azalır**.","effect_text":"ilk maçında farklı bir kötü sakatlık geçirme ihtimali %0,4 azalır","rarity":"very_rare","effect":{"metric":"different_severe_injury_risk","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kötü sakatlık sonrası ilk maç","Öncekinden farklı kötü sakatlık"]},{"content_id":"doctor_025","role_id":"doctor","profession":"doctor","ordinal":25,"title":"Kalabalık Revirin Düzeni","subtitle":"Çok sayıda yaralı için bilgi ve malzemeyi birlikte yönetebilmek.","paragraph":"Bir klan savaşının ardından tutulan revir kayıtları, Doktora birden fazla yaralının bakımını ve malzeme ihtiyacını birlikte planlamayı öğretir. Aynı klan savaşında kendi ludusundan en az iki gladyatör yaralanırsa, **ikinci ve sonraki yaralıların tedavisinde %0,8 ihtimalle gereken sarf malzemelerinden bir adet kasada kalır**. Her tedavi için bir kez hesaplanır.","effect_text":"ikinci ve sonraki yaralıların tedavisinde %0,8 ihtimalle gereken sarf malzemelerinden bir adet kasada kalır","rarity":"very_rare","effect":{"metric":"required_consumable_save","operation":"event_probability","value":0.008,"unit":"fraction"},"conditions":["Aynı klan savaşında kendi ludusundan en az iki yaralı","İkinci ve sonraki yaralılar","Her tedavi için tek hesaplama","Gereken sarf malzemesinden bir adet korunur"]},{"content_id":"doctore_001","role_id":"trainer","profession":"doctore","ordinal":1,"title":"Üç Ucun Kullanımı","subtitle":"Savunmadaki açıklığı doğru anda değerlendirmeyi öğrenmek.","paragraph":"Papirüs, tridentin üç ucuyla farklı savunmalara yöneltilen hamlelerin çizimlerini içerir. Doctore, rakibin duruşunda beliren açıklığı ve saldırının zamanını birlikte değerlendirmeyi öğrenir. Bu bilgi, ludusun trident kullanan gladyatörlerinin arena dövüşlerine yansır. Trident saldırılarında kritik vuruş ihtimali **+0,2 yüzde puan artar**.","effect_text":"Trident saldırılarında kritik vuruş ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"critical_hit_chance","operation":"add_probability","value":0.002,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"trident"}]},{"content_id":"doctore_002","role_id":"trainer","profession":"doctore","ordinal":2,"title":"Mızrakta Mesafe ve Denge","subtitle":"Silahın erişimini bedenin hareketiyle birleştirebilmek.","paragraph":"Mızrak hamlelerinin yanına düşülen notlar, mesafe ile beden dengesinin birlikte nasıl değerlendirildiğini anlatır. Doctore, silahın erişimini etkili kullanmaya ilişkin ayrıntıları öğrenir. Papirüsten edindiği bu bilgi, ludusun mızrak kullanan gladyatörlerinin arena saldırılarına pasif olarak katkıda bulunur. **Mızrakla verilen hasar %0,2 artar**.","effect_text":"Mızrakla verilen hasar %0,2 artar.","rarity":"common","effect":{"metric":"damage_dealt","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"spear"}]},{"content_id":"doctore_003","role_id":"trainer","profession":"doctore","ordinal":3,"title":"Kılıçta Hareket Ekonomisi","subtitle":"Her savuruşta gücü yerinde kullanmayı öğrenmek.","paragraph":"Papirüste kılıç savuruşları, tutuşlar ve hamle sonundaki duruşlar birlikte gösterilir. Doctore, saldırı sırasında gücün hangi hareketlerde gereksiz yere harcandığını değerlendirmeyi öğrenir. Bu bilgiyi edinmesi, ludusun kılıç kullanan gladyatörlerinin arena dövüşlerinde kendini gösterir. **Kılıç saldırılarının kondisyon tüketimi %0,4 azalır**.","effect_text":"Kılıç saldırılarının kondisyon tüketimi %0,4 azalır.","rarity":"common","effect":{"metric":"attack_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"sword"}]},{"content_id":"doctore_004","role_id":"trainer","profession":"doctore","ordinal":4,"title":"Baltayla İsabetin İncelikleri","subtitle":"Fırsat veren bir açıklıktan daha etkili yararlanabilmek.","paragraph":"Balta hamlelerini karşılaştıran çizimler, isabet anındaki açıyla rakibin duruşu arasındaki ilişkiyi anlatır. Doctore, yakalanan bir açıklığı nasıl daha etkili değerlendireceğini öğrenir. Bu ileri bilgi, ludusun balta kullanan gladyatörlerinin kritik saldırılarına yansır. **Baltayla yapılan kritik vuruşların hasarı %0,4 artar**.","effect_text":"Baltayla yapılan kritik vuruşların hasarı %0,4 artar.","rarity":"rare","effect":{"metric":"critical_hit_damage","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"axe"}]},{"content_id":"doctore_005","role_id":"trainer","profession":"doctore","ordinal":5,"title":"Teberle İki Hedefi Gözetmek","subtitle":"Bir savuruş sırasında ikinci rakibin yerini okuyabilmek.","paragraph":"Papirüs, birbirine yakın iki rakibe karşı kullanılan teber hamlelerini farklı açılardan gösterir. Doctore, ilk hedefe yönelirken ikinci hedefin konumunu da değerlendirmeyi öğrenir. Bu bilgiyi edinmesi, ludusun teber kullanan gladyatörlerinin özel alan saldırısını geliştirir. **İkinci hedefe hesaplanan hasar %0,4 artar**.","effect_text":"Teberin özel alan saldırısında ikinci hedefe hesaplanan hasar %0,4 artar.","rarity":"unique","effect":{"metric":"damage_dealt","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"halberd"},{"field":"action","operator":"eq","value":"special_area_attack"},{"field":"target_position","operator":"eq","value":"second"}]},{"content_id":"doctore_006","role_id":"trainer","profession":"doctore","ordinal":6,"title":"Gürzle Kalkanı Zorlamak","subtitle":"Ağır bir hamlede gücü doğru yönlendirmeyi öğrenmek.","paragraph":"Kalkana yöneltilen gürz darbelerine ait çizimler, tutuş ve beden hareketinin birlikte kullanımını anlatır. Doctore, kalkan kırmaya yönelik özel hamlede harcanan gücü daha iyi değerlendirmeyi öğrenir. Bu bilgi, ludusun gürz kullanan gladyatörlerinin arena dövüşlerine aktarılır. **Kalkan kırma özel hareketinin kondisyon tüketimi %0,4 azalır**.","effect_text":"Gürzün kalkan kırma özel hareketinin kondisyon tüketimi %0,4 azalır.","rarity":"rare","effect":{"metric":"action_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"mace"},{"field":"action","operator":"eq","value":"shield_break_special"}]},{"content_id":"doctore_007","role_id":"trainer","profession":"doctore","ordinal":7,"title":"Çekiçte Ağırlığın Kullanımı","subtitle":"Silahın ağırlığını etkili bir darbeye dönüştürebilmek.","paragraph":"Papirüs, çekicin kaldırılışından isabetine kadar uzanan hareketi çizimler ve kısa gözlemlerle anlatır. Doctore, ağırlık ile savuruş arasındaki ilişkiyi değerlendirmeyi öğrenir. Edindiği bu bilgi, ludusun çekiç kullanan gladyatörlerinin arena saldırılarına pasif olarak katkıda bulunur. **Çekiçle verilen hasar %0,2 artar**.","effect_text":"Çekiçle verilen hasar %0,2 artar.","rarity":"common","effect":{"metric":"damage_dealt","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"hammer"}]},{"content_id":"doctore_008","role_id":"trainer","profession":"doctore","ordinal":8,"title":"Ağın Açılışını Yönetmek","subtitle":"Atışın hazırlığını ve bırakışını birlikte öğrenmek.","paragraph":"Ağın toplanışı, elde taşınışı ve bırakılışı aynı papirüs üzerinde gösterilir. Doctore, atışın her aşamasında gücün nasıl kullanıldığını ve hareketlerin birbirini nasıl tamamladığını öğrenir. Bu bilgi, ludusun ağ kullanan gladyatörlerinin arena dövüşlerine yansır. **Ağ atmanın kondisyon tüketimi %0,4 azalır**.","effect_text":"Ağ atmanın kondisyon tüketimi %0,4 azalır.","rarity":"rare","effect":{"metric":"action_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"net"},{"field":"action","operator":"eq","value":"net_throw"}]},{"content_id":"doctore_009","role_id":"trainer","profession":"doctore","ordinal":9,"title":"Kırbaçta Çekişin Dengesi","subtitle":"Gerilimi ve beden desteğini birlikte değerlendirebilmek.","paragraph":"Papirüsteki hamle çizimleri, kırbaçla çekiş sırasında kolun ve gövdenin aldığı konumları karşılaştırır. Doctore, çekme hareketinde kullanılan gücü daha bilinçli yönlendirmeyi öğrenir. Bu becerinin bilgisi, ludusun kırbaç kullanan gladyatörlerine arena dövüşlerinde pasif katkı sağlar. **Kırbaçla çekme hareketinin kondisyon tüketimi %0,4 azalır**.","effect_text":"Kırbaçla çekme hareketinin kondisyon tüketimi %0,4 azalır.","rarity":"rare","effect":{"metric":"action_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"whip"},{"field":"action","operator":"eq","value":"whip_pull"}]},{"content_id":"doctore_010","role_id":"trainer","profession":"doctore","ordinal":10,"title":"Büyük Kalkanın Ardındaki Duruş","subtitle":"Geniş bir savunmayı dengeli biçimde taşıyabilmek.","paragraph":"Büyük kalkanla karşılanan farklı darbeler, ayakların ve kalkan kolunun konumlarıyla birlikte çizilmiştir. Doctore, savunma sırasında harcanan gücü duruşla birlikte değerlendirmeyi öğrenir. Papirüsten edinilen bu bilgi, ludusun büyük kalkan kullanan gladyatörlerine aktarılır. **Başarılı bloklarda harcanan kondisyon %0,4 azalır**.","effect_text":"Büyük kalkanla başarılı bloklarda harcanan kondisyon %0,4 azalır.","rarity":"common","effect":{"metric":"action_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"shield_size","operator":"eq","value":"large"},{"field":"block_successful","operator":"eq","value":true}]},{"content_id":"doctore_011","role_id":"trainer","profession":"doctore","ordinal":11,"title":"Küçük Kalkanda Yön ve Zaman","subtitle":"Dar bir koruma alanını doğru konumlandırabilmek.","paragraph":"Papirüs, küçük ve orta kalkanlarla yapılan savunmaları darbenin yönüyle birlikte gösterir. Doctore, kalkanın yerini ve karşılamanın zamanını değerlendirmeyi öğrenir. Edindiği bu bilgi, ludusun küçük veya orta kalkan kullanan gladyatörlerinin arena savunmasına yansır. **Başarılı bloklarda harcanan kondisyon %0,4 azalır**.","effect_text":"Küçük veya orta kalkanla başarılı bloklarda harcanan kondisyon %0,4 azalır.","rarity":"common","effect":{"metric":"action_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"shield_size","operator":"in","value":["small","medium"]},{"field":"block_successful","operator":"eq","value":true}]},{"content_id":"doctore_012","role_id":"trainer","profession":"doctore","ordinal":12,"title":"Miğferle Korunmanın Esasları","subtitle":"Başın duruşuyla miğferin korumasını birlikte kullanabilmek.","paragraph":"Miğferli gladyatörlerin farklı savunma duruşlarını gösteren çizimler, başın konumuyla korunan bölge arasındaki ilişkiyi anlatır. Doctore, ekipmanın korumasından daha iyi yararlanmayı öğrenir. Bu bilgi ludusun gladyatörlerinin arena savunmasına pasif olarak katkıda bulunur. **Takılı miğferin koruduğu baş bölgesine gelen hasar %0,2 azalır**.","effect_text":"Takılı miğferin koruduğu baş bölgesine gelen hasar %0,2 azalır.","rarity":"common","effect":{"metric":"damage_received","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"equipped_protection","operator":"eq","value":"helmet"},{"field":"hit_region","operator":"eq","value":"head"},{"field":"hit_region_covered_by_equipment","operator":"eq","value":true}]},{"content_id":"doctore_013","role_id":"trainer","profession":"doctore","ordinal":13,"title":"Zırhla Gövdeyi Korumak","subtitle":"Bedenin yönünü zırhın örttüğü alanla birlikte düşünmek.","paragraph":"Papirüs, göğüs zırhı taşıyan gladyatörlerin saldırı karşısında aldığı duruşları gösterir. Doctore, gövdenin yönüyle zırhın koruduğu bölgeyi birlikte değerlendirmeyi öğrenir. Bu bilgi, ludusun zırh kuşanmış gladyatörlerinin arena savunmasına yansır. **Takılı göğüs zırhının koruduğu bölgeye gelen hasar %0,2 azalır**.","effect_text":"Takılı göğüs zırhının koruduğu bölgeye gelen hasar %0,2 azalır.","rarity":"common","effect":{"metric":"damage_received","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"equipped_protection","operator":"eq","value":"chest_armor"},{"field":"hit_region","operator":"eq","value":"torso"},{"field":"hit_region_covered_by_equipment","operator":"eq","value":true}]},{"content_id":"doctore_014","role_id":"trainer","profession":"doctore","ordinal":14,"title":"Kollukla Savunmanın İncelikleri","subtitle":"Hareket eden kolun korumasını bilinçli kullanabilmek.","paragraph":"Silah tutan kolun farklı konumlarını karşılaştıran çizimler, kolluğun örttüğü alanı hareket boyunca takip eder. Doctore, kolun duruşuyla ekipmanın korumasını birlikte değerlendirmeyi öğrenir. Bu bilgi, ludusun kolluk kuşanmış gladyatörlerinin arena savunmasına pasif katkı sağlar. **Takılı kolluğun koruduğu kola gelen hasar %0,2 azalır**.","effect_text":"Takılı kolluğun koruduğu kola gelen hasar %0,2 azalır.","rarity":"common","effect":{"metric":"damage_received","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"equipped_protection","operator":"eq","value":"manica"},{"field":"hit_region","operator":"eq","value":"arm"},{"field":"hit_region_covered_by_equipment","operator":"eq","value":true}]},{"content_id":"doctore_015","role_id":"trainer","profession":"doctore","ordinal":15,"title":"Bacaklıkla Dengeli Savunma","subtitle":"Adım atarken korunan bölgenin konumunu gözetebilmek.","paragraph":"Papirüs, bacaklık taşıyan gladyatörlerin ilerlerken ve savunmaya çekilirken aldığı duruşları anlatır. Doctore, adımla birlikte bacağın korunan bölgesini konumlandırmayı öğrenir. Edindiği bu bilgi, ludusun bacaklık kuşanmış gladyatörlerinin arena savunmasına yansır. **Takılı bacaklığın koruduğu bölgeye gelen hasar %0,2 azalır**.","effect_text":"Takılı bacaklığın koruduğu bölgeye gelen hasar %0,2 azalır.","rarity":"common","effect":{"metric":"damage_received","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"equipped_protection","operator":"eq","value":"greave"},{"field":"hit_region","operator":"eq","value":"leg"},{"field":"hit_region_covered_by_equipment","operator":"eq","value":true}]},{"content_id":"doctore_016","role_id":"trainer","profession":"doctore","ordinal":16,"title":"Kılıçla Açığı Değerlendirmek","subtitle":"İsabet eden bir hamlenin etkisini güçlendirmeyi öğrenmek.","paragraph":"Papirüs, rakibin savunmasında beliren açıklığa yöneltilmiş kılıç hamlelerini karşılaştırır. Doctore, isabet anındaki açıyla bedenin hareketini birlikte değerlendirmeyi öğrenir. Edindiği bu bilgi, ludusun kılıç kullanan gladyatörlerinin arenada yakaladıkları fırsatlara yansır. **Kılıçla yapılan kritik vuruşların hasarı %0,4 artar**.","effect_text":"Kılıçla yapılan kritik vuruşların hasarı %0,4 artar.","rarity":"very_rare","effect":{"metric":"critical_hit_damage","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"sword"}]},{"content_id":"doctore_017","role_id":"trainer","profession":"doctore","ordinal":17,"title":"Mızrağı Fırlatmanın Esasları","subtitle":"Atış sırasında gücü ve bırakış anını birlikte yönetebilmek.","paragraph":"Mızrak atışının aşamalarını gösteren çizimler, hazırlık duruşundan silahın bırakılmasına kadar uzanan hareketi anlatır. Doctore, atış sırasında harcanan gücün nasıl değerlendirileceğini öğrenir. Bu bilgi ludusun mızrak kullanan gladyatörlerinin özel hareketine pasif katkı sağlar. **Mızrak fırlatmanın kondisyon tüketimi %0,4 azalır**.","effect_text":"Mızrak fırlatmanın kondisyon tüketimi %0,4 azalır.","rarity":"rare","effect":{"metric":"action_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"spear"},{"field":"action","operator":"eq","value":"spear_throw"}]},{"content_id":"doctore_018","role_id":"trainer","profession":"doctore","ordinal":18,"title":"Tridenti Fırlatmanın Dengesi","subtitle":"Silahın dengesini tanıyarak atışı tamamlayabilmek.","paragraph":"Papirüste tridentin ağırlığıyla atış tutuşunu birlikte ele alan çizimler bulunur. Doctore, hazırlık ve bırakış sırasında bedenin dengesini gözetmeyi öğrenir. Bu bilgi, ludusun trident kullanan gladyatörlerinin arena dövüşlerinde uyguladığı özel harekete yansır. **Trident fırlatmanın kondisyon tüketimi %0,4 azalır**.","effect_text":"Trident fırlatmanın kondisyon tüketimi %0,4 azalır.","rarity":"rare","effect":{"metric":"action_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"trident"},{"field":"action","operator":"eq","value":"trident_throw"}]},{"content_id":"doctore_019","role_id":"trainer","profession":"doctore","ordinal":19,"title":"Baltada Savuruş Düzeni","subtitle":"Darbenin ardından gelen hareketi de bilinçli yönetmek.","paragraph":"Birbirini izleyen balta savuruşlarının çizimleri, hamle başlangıcıyla sonraki duruş arasındaki ilişkiyi gösterir. Doctore, saldırı sırasında gücün gereksiz harcandığı hareketleri ayırt etmeyi öğrenir. Bu bilgi ludusun balta kullanan gladyatörlerinin arena dövüşlerine yansır. **Baltayla yapılan normal saldırıların kondisyon tüketimi %0,4 azalır**.","effect_text":"Baltayla yapılan normal saldırıların kondisyon tüketimi %0,4 azalır.","rarity":"common","effect":{"metric":"attack_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"axe"},{"field":"action","operator":"eq","value":"normal_attack"}]},{"content_id":"doctore_020","role_id":"trainer","profession":"doctore","ordinal":20,"title":"Teberde Tutuş ve Savuruş","subtitle":"Uzun bir silahı dengeli hareketlerle kullanabilmek.","paragraph":"Papirüs, teberin sapındaki tutuşla savuruş boyunca değişen beden konumlarını birlikte gösterir. Doctore, silahın hareketini daha ölçülü biçimde yönlendirmeyi öğrenir. Bu bilgi, ludusun teber kullanan gladyatörlerinin arenadaki günlük dövüş becerisine katkıda bulunur. **Teberle yapılan normal saldırıların kondisyon tüketimi %0,4 azalır**.","effect_text":"Teberle yapılan normal saldırıların kondisyon tüketimi %0,4 azalır.","rarity":"rare","effect":{"metric":"attack_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"halberd"},{"field":"action","operator":"eq","value":"normal_attack"}]},{"content_id":"doctore_021","role_id":"trainer","profession":"doctore","ordinal":21,"title":"Çekiçle Kalkanı Zorlamak","subtitle":"Dirençli bir savunmaya karşı gücü yerinde kullanmak.","paragraph":"Kalkanlara yöneltilen çekiç darbelerine ait çizimler, tutuş ile darbe yönünün birlikte değerlendirilmesini anlatır. Doctore, kalkanı kırmaya yönelik özel harekette harcanan gücü daha iyi yönetmeyi öğrenir. Bu bilgi ludusun çekiç kullanan gladyatörlerine aktarılır. **Çekiçle kalkan kırma özel hareketinin kondisyon tüketimi %0,4 azalır**.","effect_text":"Çekiçle kalkan kırma özel hareketinin kondisyon tüketimi %0,4 azalır.","rarity":"very_rare","effect":{"metric":"action_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"hammer"},{"field":"action","operator":"eq","value":"shield_break_special"}]},{"content_id":"doctore_022","role_id":"trainer","profession":"doctore","ordinal":22,"title":"Kalkanla İtişin Esasları","subtitle":"Savunma aracını kontrollü bir itişte kullanabilmek.","paragraph":"Papirüs, kalkanla itiş sırasında ayakların ve gövdenin aldığı konumları gösterir. Doctore, özel hareketin gücünü bedenin dengesini gözeterek yönlendirmeyi öğrenir. Edindiği bu bilgi, ludusun kalkan kullanan gladyatörlerinin arenada yaptığı itişe pasif katkıda bulunur. **Kalkanla itme özel hareketinin kondisyon tüketimi %0,4 azalır**.","effect_text":"Kalkanla itme özel hareketinin kondisyon tüketimi %0,4 azalır.","rarity":"very_rare","effect":{"metric":"action_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"equipment_type","operator":"eq","value":"shield"},{"field":"action","operator":"eq","value":"shield_push_special"}]},{"content_id":"doctore_023","role_id":"trainer","profession":"doctore","ordinal":23,"title":"Tridentte Hareket Ekonomisi","subtitle":"Her hamlede silahın ağırlığını ve dönüşünü gözetebilmek.","paragraph":"Trident hamlelerini birbirine bağlayan çizimler, saldırının başlangıcını ve silahın yeniden konumlanmasını birlikte anlatır. Doctore, bu hareketlerde gücün nasıl korunduğunu öğrenir. Papirüsten edinilen bilgi, ludusun trident kullanan gladyatörlerinin arena dövüşlerine yansır. **Tridentle yapılan normal saldırıların kondisyon tüketimi %0,4 azalır**.","effect_text":"Tridentle yapılan normal saldırıların kondisyon tüketimi %0,4 azalır.","rarity":"common","effect":{"metric":"attack_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"trident"},{"field":"action","operator":"eq","value":"normal_attack"}]},{"content_id":"doctore_024","role_id":"trainer","profession":"doctore","ordinal":24,"title":"Kırbaçta İsabetin Bilgisi","subtitle":"Mesafe ile savuruşu birlikte değerlendirmeyi öğrenmek.","paragraph":"Papirüste farklı mesafelerden yapılan kırbaç savuruşları, rakibin duruşuyla birlikte gösterilir. Doctore, saldırının isabetini etkili kullanmaya ilişkin ayrıntıları öğrenir. Bu bilgi, ludusun kırbaç kullanan gladyatörlerinin arenada yaptığı normal saldırılara pasif olarak katkıda bulunur. **Kırbaçla yapılan normal saldırıların hasarı %0,2 artar**.","effect_text":"Kırbaçla yapılan normal saldırıların hasarı %0,2 artar.","rarity":"very_rare","effect":{"metric":"damage_dealt","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"whip"},{"field":"action","operator":"eq","value":"normal_attack"}]},{"content_id":"doctore_025","role_id":"trainer","profession":"doctore","ordinal":25,"title":"Gürzde Darbenin Yönü","subtitle":"Silahın ağırlığını hedefe bilinçli yönlendirebilmek.","paragraph":"Gürz saldırılarını karşılaştıran çizimler, savuruş açısını ve isabet anındaki beden konumunu anlatır. Doctore, silahın ağırlığını etkili bir darbeye dönüştürmenin ayrıntılarını öğrenir. Bu bilgi ludusun gürz kullanan gladyatörlerinin arena dövüşlerine pasif katkı sağlar. **Gürzle yapılan normal saldırıların hasarı %0,2 artar**.","effect_text":"Gürzle yapılan normal saldırıların hasarı %0,2 artar.","rarity":"rare","effect":{"metric":"damage_dealt","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":[{"field":"mode","operator":"eq","value":"arena"},{"field":"beneficiary","operator":"eq","value":"own_ludus_gladiator"},{"field":"weapon_type","operator":"eq","value":"mace"},{"field":"action","operator":"eq","value":"normal_attack"}]},{"content_id":"chef_001","role_id":"cook","profession":"chef","ordinal":1,"title":"Arena Öncesi Beslenmenin Temelleri","subtitle":"Bir öğünün dövüş boyunca taşıdığı gücü anlayabilmek.","paragraph":"Papirüs, farklı öğünlerle arenaya çıkan gladyatörlerin dayanma gücüne ilişkin notlar içerir. Aşçı bu gözlemleri okuyarak maç öncesi beslenmenin kondisyon sınırına katkısını öğrenir. Bu bilgi, ilgili kondisyon öğününün hazırlanmasına yansır. Bu öğünü yiyen gladyatörün maksimum kondisyonu %0,2 artar.","effect_text":"Maksimum kondisyon +%0,2","rarity":"common","effect":{"metric":"maximum_arena_stamina","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":[]},{"content_id":"chef_002","role_id":"cook","profession":"chef","ordinal":2,"title":"Koşuya Uygun Beslenme","subtitle":"Hareketin gerektirdiği enerjiyi öğünde hesaba katabilmek.","paragraph":"Koşu ağırlıklı dövüşlerin ardından tutulan kayıtlar, Aşçıya hareketli bir gladyatörün beslenme ihtiyacını öğretir. Bu bilgiyi öğrenen Aşçı, hazırladığı öğünü uzun süre hareket etmeyi destekleyecek şekilde değerlendirebilir. Bu öğünü yiyen gladyatör koşarken %0,2 daha az kondisyon harcar.","effect_text":"Koşuda kondisyon tüketimi −%0,2","rarity":"common","effect":{"metric":"running_stamina_cost","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Gladyatör koşarken."]},{"content_id":"chef_003","role_id":"cook","profession":"chef","ordinal":3,"title":"Saldırı Temposunu Beslemek","subtitle":"Tekrarlanan vuruşların yükünü anlayabilmek.","paragraph":"Papirüsteki gözlemler, art arda saldıran gladyatörlerin harcadığı kondisyonla öğün hazırlığı arasındaki ilişkiyi anlatır. Aşçı, dövüşün saldırı temposuna uygun beslenme hazırlamayı öğrenerek gladyatörün gücünü daha verimli kullanmasına katkıda bulunur. Bu öğünü yiyen gladyatör normal saldırılarda %0,2 daha az kondisyon harcar.","effect_text":"Normal saldırıda kondisyon tüketimi −%0,2","rarity":"common","effect":{"metric":"normal_attack_stamina_cost","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Gladyatör normal saldırı yaparken."]},{"content_id":"chef_004","role_id":"cook","profession":"chef","ordinal":4,"title":"Savunmaya Uygun Beslenme","subtitle":"Darbeyi karşılamanın gerektirdiği gücü tanımak.","paragraph":"Kalkan başında geçen uzun dövüşlerin kayıtları, Aşçıya savunma sırasında harcanan kondisyonu öğretir. Bu bilgiyi öğün hazırlığına kattığında gladyatörün darbeleri karşılamak için ayırdığı güçten daha iyi yararlanmasına yardımcı olur. Bu öğünü yiyen gladyatör başarılı bloklarda %0,2 daha az kondisyon harcar.","effect_text":"Başarılı blokta kondisyon tüketimi −%0,2","rarity":"common","effect":{"metric":"successful_block_stamina_cost","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Gladyatör başarılı blok yaptığında."]},{"content_id":"chef_005","role_id":"cook","profession":"chef","ordinal":5,"title":"Çevik Hareketler İçin Beslenme","subtitle":"Ani hareketlerde bedenin ihtiyacını gözetebilmek.","paragraph":"Papirüs, yuvarlanarak saldırılardan sıyrılan gladyatörlerin öğünlerine ilişkin gözlemleri bir araya getirir. Aşçı bu bilgiyi öğrenerek çevik hareketlerin tekrarlanmasını destekleyen bir beslenme hazırlığı yapmayı ve kondisyon kullanımını gözetmeyi öğrenir. Bu öğünü yiyen gladyatör yuvarlanırken %0,2 daha az kondisyon harcar.","effect_text":"Yuvarlanmada kondisyon tüketimi −%0,2","rarity":"common","effect":{"metric":"roll_stamina_cost","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Gladyatör yuvarlanırken."]},{"content_id":"chef_006","role_id":"cook","profession":"chef","ordinal":6,"title":"Özel Hamleye Hazırlık","subtitle":"Kısa sürede harcanan yoğun gücü öğünde karşılayabilmek.","paragraph":"Silaha özgü hareketlerin ardından tutulan notlar, Aşçıya tek hamlede harcanan kondisyonun önemini anlatır. Aşçı, gladyatörün belirleyici hareketini kullanırken ihtiyaç duyduğu gücü destekleyecek öğün hazırlama bilgisini kalıcı olarak edinir. Bu öğünü yiyen gladyatör özel hareketlerde %0,2 daha az kondisyon harcar.","effect_text":"Özel harekette kondisyon tüketimi −%0,2","rarity":"common","effect":{"metric":"special_action_stamina_cost","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Gladyatör özel hareket kullanırken."]},{"content_id":"chef_007","role_id":"cook","profession":"chef","ordinal":7,"title":"Soluklanmayı Destekleyen Beslenme","subtitle":"Dövüş aralarında toparlanmanın değerini anlayabilmek.","paragraph":"Papirüs, kısa soluklanma araları bulan gladyatörlerin yeniden dövüşe hazırlanmasını konu alır. Aşçı bu gözlemlerden, beslenmenin dinlenme anlarında kondisyonun toparlanmasına nasıl katkı sunduğunu öğrenir ve bilgiyi hazırladığı öğüne aktarır. Bu öğünü yiyen gladyatörün kondisyon yenilenme hızı %0,2 artar.","effect_text":"Kondisyon yenilenme hızı +%0,2","rarity":"common","effect":{"metric":"stamina_regeneration_rate","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":[]},{"content_id":"chef_008","role_id":"cook","profession":"chef","ordinal":8,"title":"Tükenen Gücü Desteklemek","subtitle":"Kondisyonun en düşük olduğu anlara hazırlanabilmek.","paragraph":"Uzun dövüşlerin son bölümüne ait kayıtlar, Aşçıya gücü azalan gladyatörlerin ihtiyaçlarını öğretir. Bu ileri beslenme bilgisi, gladyatörün zorlandığı anlarda toparlanmasını destekleyen öğünleri daha bilinçli hazırlamasını sağlar. Bu öğünü yiyen gladyatörün kondisyonu %25’in altındayken kondisyon yenilenme hızı %0,4 artar.","effect_text":"Kondisyon %25’in altındayken yenilenme hızı +%0,4","rarity":"common","effect":{"metric":"stamina_regeneration_rate","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Gladyatörün kondisyonu %25’in altındayken."]},{"content_id":"chef_009","role_id":"cook","profession":"chef","ordinal":9,"title":"Uzun Dövüşün Beslenme Düzeni","subtitle":"Bir öğünün uzun süreli dayanma gücüne katkısını öğrenmek.","paragraph":"Papirüs, süresi uzayan müsabakalarda beslenmenin üstlendiği rolü ayrıntılı gözlemlerle anlatır. Aşçı, gladyatörün maç boyunca kullanabileceği kondisyonu destekleyen öğünlerin hazırlanmasına ilişkin bilgisini derinleştirir ve bu bilgiyi kalıcı bir beceriye dönüştürür. Bu öğünü yiyen gladyatörün maksimum kondisyonu %0,4 artar.","effect_text":"Maksimum kondisyon +%0,4","rarity":"rare","effect":{"metric":"maximum_arena_stamina","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":[]},{"content_id":"chef_010","role_id":"cook","profession":"chef","ordinal":10,"title":"Kalkan Taşıyan Bedenin İhtiyacı","subtitle":"Savunmanın uzun süren yüküne uygun öğün hazırlayabilmek.","paragraph":"Kalkanla geçirilen ağır müsabakaların notları, Aşçıya başarılı blokların tekrarlanması için gereken kondisyonu öğretir. Genel savunma beslenmesi bilgisini derinleştiren Aşçı, hazırladığı öğünle gladyatörün kalkan başındaki gücünü daha verimli kullanmasını destekler. Bu öğünü yiyen gladyatör başarılı bloklarda %0,4 daha az kondisyon harcar.","effect_text":"Başarılı blokta kondisyon tüketimi −%0,4","rarity":"rare","effect":{"metric":"successful_block_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Gladyatör başarılı blok yaptığında."]},{"content_id":"chef_011","role_id":"cook","profession":"chef","ordinal":11,"title":"Kesintisiz Saldırının Beslenmesi","subtitle":"Vuruşlar arasında gücü korumayı öğünle desteklemek.","paragraph":"Papirüsteki dövüş kayıtları, normal saldırılarını sık tekrarlayan gladyatörlerin beslenme ihtiyacını karşılaştırır. Aşçı, bu gözlemlerden saldırı temposunu beslemeye ilişkin ileri bilgi edinir ve gladyatörün art arda vuruşlarda kondisyonunu daha iyi değerlendirmesini sağlar. Bu öğünü yiyen gladyatör normal saldırılarda %0,4 daha az kondisyon harcar.","effect_text":"Normal saldırıda kondisyon tüketimi −%0,4","rarity":"rare","effect":{"metric":"normal_attack_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Gladyatör normal saldırı yaparken."]},{"content_id":"chef_012","role_id":"cook","profession":"chef","ordinal":12,"title":"Çevikliğin Beslenme Bilgisi","subtitle":"Tekrarlanan kaçınma hareketlerine hazırlanabilmek.","paragraph":"Birçok müsabakadan toplanan notlar, yuvarlanarak konum değiştiren gladyatörlerin harcadığı gücü inceler. Aşçı bu bilgiyi öğrenerek kaçınma hareketlerine uygun öğün hazırlığında ustalaşır ve gladyatörün çevikliğini sürdürmek için ayırdığı kondisyonu destekler. Bu öğünü yiyen gladyatör yuvarlanırken %0,4 daha az kondisyon harcar.","effect_text":"Yuvarlanmada kondisyon tüketimi −%0,4","rarity":"rare","effect":{"metric":"roll_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Gladyatör yuvarlanırken."]},{"content_id":"chef_013","role_id":"cook","profession":"chef","ordinal":13,"title":"Uzun Takibin Beslenmesi","subtitle":"Hareketi sürdürmek için gereken gücü planlayabilmek.","paragraph":"Rakibini uzun süre takip eden gladyatörlerin kayıtları, Aşçıya koşunun dövüşteki kondisyon maliyetini gösterir. Öğrendiği ileri beslenme bilgisi sayesinde hareketliliği destekleyen öğünleri daha bilinçli hazırlar ve koşuya ayrılan gücün kullanımını iyileştirir. Bu öğünü yiyen gladyatör koşarken %0,4 daha az kondisyon harcar.","effect_text":"Koşuda kondisyon tüketimi −%0,4","rarity":"rare","effect":{"metric":"running_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Gladyatör koşarken."]},{"content_id":"chef_014","role_id":"cook","profession":"chef","ordinal":14,"title":"Soluk Tazelemenin Beslenme Bilgisi","subtitle":"Kısa aralardan daha iyi toparlanarak çıkabilmek.","paragraph":"Papirüs, dövüş sırasında bulunan soluklanma fırsatlarına ilişkin ayrıntılı gözlemler içerir. Aşçı, gladyatörün bu aralarda kondisyonunu toplamasını destekleyen beslenme bilgisinde ustalaşır ve hazırladığı öğünle yeniden harekete geçişini daha iyi destekler. Bu öğünü yiyen gladyatörün kondisyon yenilenme hızı %0,4 artar.","effect_text":"Kondisyon yenilenme hızı +%0,4","rarity":"rare","effect":{"metric":"stamina_regeneration_rate","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":[]},{"content_id":"chef_015","role_id":"cook","profession":"chef","ordinal":15,"title":"Belirleyici Hamlenin Beslenmesi","subtitle":"Özel harekete ayrılan gücü verimli kullanmayı öğrenmek.","paragraph":"Farklı silahların özel hareketlerinden sonra alınmış notlar, Aşçıya yoğun kondisyon harcamasına uygun beslenmeyi öğretir. Bu ileri bilgi, hazırladığı öğünün gladyatörün belirleyici hamlesini daha az güç harcayarak kullanmasına katkı sunmasını sağlar. Bu öğünü yiyen gladyatör özel hareketlerde %0,4 daha az kondisyon harcar.","effect_text":"Özel harekette kondisyon tüketimi −%0,4","rarity":"rare","effect":{"metric":"special_action_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Gladyatör özel hareket kullanırken."]},{"content_id":"chef_016","role_id":"cook","profession":"chef","ordinal":16,"title":"Kayarak Kaçınmaya Uygun Beslenme","subtitle":"Yere yakın hareketlerin kondisyon ihtiyacını anlayabilmek.","paragraph":"Papirüs, rakibin saldırısından kayarak uzaklaşan gladyatörlerin öğün hazırlıklarına ilişkin notlar taşır. Aşçı bu hareketin gerektirdiği gücü öğrenir ve hazırladığı öğünle gladyatörün arenada konum değiştirirken kondisyonunu daha verimli kullanmasını destekler. Kayma hareketinde kondisyon tüketimi %0,4 azalır.","effect_text":"Kayma hareketinde kondisyon tüketimi %0,4 azalır.","rarity":"common","effect":{"metric":"slide_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Gladyatör kayma hareketini kullanırken."]},{"content_id":"chef_017","role_id":"cook","profession":"chef","ordinal":17,"title":"Soluklanmaya Geçişin Beslenmesi","subtitle":"Hareketin ardından toparlanmaya hazırlanmayı öğrenmek.","paragraph":"Dövüşün kısa duraklamalarına ait gözlemler, Aşçıya harcanan gücün yeniden toplanmaya başladığı aralığı öğretir. Bu bilgiyi öğrenen Aşçı, hazırladığı öğünü gladyatörün hareket sonrasında soluklanmaya daha çabuk geçmesini destekleyecek biçimde değerlendirir. Kondisyon harcayan hareketlerden sonra yenilenmenin başlaması için gereken bekleme süresi %0,4 kısalır.","effect_text":"Kondisyon harcayan hareketlerden sonra yenilenmenin başlaması için gereken bekleme süresi %0,4 kısalır.","rarity":"rare","effect":{"metric":"stamina_regeneration_start_delay","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kondisyon harcayan bir hareketin ardından yenilenme bekleme süresi işlerken."]},{"content_id":"chef_018","role_id":"cook","profession":"chef","ordinal":18,"title":"Yerden Kalkışın Hazırlığı","subtitle":"Düşüşten sonra yeniden dövüşe dönmenin yükünü öğrenmek.","paragraph":"Papirüs, yere düşüp tekrar ayağa kalkan gladyatörlerin dövüşe dönüşünü konu alır. Aşçı, bu geçişte gereken gücü öğün hazırlığında gözetmeyi öğrenir ve gladyatörün yeniden hareket etmesini destekleyen bir bilgi kazanır. Maçta yere düşürüldükten sonra ilk ayağa kalkışta maksimum kondisyonun %0,2’si geri kazanılır. Etki maç başına bir kez uygulanır.","effect_text":"Maçta yere düşürüldükten sonra ilk ayağa kalkışta maksimum kondisyonun %0,2’si geri kazanılır.","rarity":"common","effect":{"metric":"stamina_restore","operation":"fraction_of_maximum","value":0.002,"unit":"fraction"},"conditions":["Rakibin etkisiyle yere düşürüldükten sonraki ayağa kalkışta.","Maç başına bir kez."]},{"content_id":"chef_019","role_id":"cook","profession":"chef","ordinal":19,"title":"Üstünlük Sonrası Toparlanma","subtitle":"Bir mücadelenin sonundan sonraki geçişi destekleyebilmek.","paragraph":"Rakibini alt eden gladyatörlerin dövüşe devam ettiği anlara ilişkin kayıtlar, Aşçıya kısa toparlanma fırsatlarını öğretir. Bu bilgiyi öğrenen Aşçı, bir sonraki mücadeleye geçerken kalan gücü destekleyen öğün hazırlığında beceri kazanır. Maçtaki ilk rakip öldürmede maksimum kondisyonun %0,4’ü geri kazanılır. Etki maç başına bir kez uygulanır.","effect_text":"Maçtaki ilk rakip öldürmede maksimum kondisyonun %0,4’ü geri kazanılır.","rarity":"very_rare","effect":{"metric":"stamina_restore","operation":"fraction_of_maximum","value":0.004,"unit":"fraction"},"conditions":["Gladyatörün maçtaki ilk rakip öldürmesinde.","Maç başına bir kez."]},{"content_id":"chef_020","role_id":"cook","profession":"chef","ordinal":20,"title":"Güç Azalırken Savunmayı Beslemek","subtitle":"Zor bir bloktan sonra toparlanmayı destekleyebilmek.","paragraph":"Papirüs, kondisyonu azalmış gladyatörlerin savunmayı sürdürme çabasına ilişkin notlar içerir. Aşçı, gücün tükenmeye yaklaştığı anda başarılı bir savunmanın ardından gereken desteği öğrenir ve bu bilgiyi maç öncesi hazırladığı öğüne katar. Kondisyon %25’in altındayken yapılan ilk başarılı bloktan sonra maksimum kondisyonun %0,2’si geri kazanılır. Etki maç başına bir kez uygulanır.","effect_text":"Kondisyon %25’in altındayken yapılan ilk başarılı bloktan sonra maksimum kondisyonun %0,2’si geri kazanılır.","rarity":"very_rare","effect":{"metric":"stamina_restore","operation":"fraction_of_maximum","value":0.002,"unit":"fraction"},"conditions":["Blok öncesinde kondisyon %25’in altındaysa.","Başarılı bloktan sonra.","Maç başına bir kez."]},{"content_id":"chef_021","role_id":"cook","profession":"chef","ordinal":21,"title":"Vuruş Ritmini Desteklemek","subtitle":"İsabetli saldırılar arasındaki sürekliliği anlayabilmek.","paragraph":"Art arda isabet ettirilen saldırıların kayıtları, Aşçıya dövüş ritmi içinde kullanılan gücü öğretir. Aşçı, gladyatörün bu ritmi sürdürmesine uygun öğün hazırlama bilgisi kazanır ve saldırılar arasındaki kondisyon desteğini daha bilinçli değerlendirir. Art arda üç normal saldırı isabet ettirildiğinde maksimum kondisyonun %0,2’si geri kazanılır. Etki maç başına bir kez uygulanır. Aradaki başarısız normal saldırı diziyi sıfırlar.","effect_text":"Art arda üç normal saldırı isabet ettirildiğinde maksimum kondisyonun %0,2’si geri kazanılır. Etki maç başına bir kez uygulanır.","rarity":"very_rare","effect":{"metric":"stamina_restore","operation":"fraction_of_maximum","value":0.002,"unit":"fraction"},"conditions":["Üç normal saldırı art arda rakibe isabet ettiğinde.","Aradaki başarısız normal saldırı diziyi sıfırlar.","Maç başına bir kez."]},{"content_id":"chef_022","role_id":"cook","profession":"chef","ordinal":22,"title":"Geniş Hamleden Sonra Toparlanma","subtitle":"Birden çok rakibe yönelen hareketin yükünü öğrenmek.","paragraph":"Papirüs, aynı özel hareketle birden fazla rakibe ulaşan gladyatörlerin harcadığı gücü anlatır. Aşçı, geniş bir saldırının ardından kondisyonu destekleyecek öğün hazırlığını öğrenir ve bu bilgiyi kalıcı bir mutfak becerisine dönüştürür. Bir özel hareket en az iki farklı rakibe isabet ederse maksimum kondisyonun %0,2’si geri kazanılır. Her özel harekette bir kez uygulanır.","effect_text":"Bir özel hareket en az iki farklı rakibe isabet ederse maksimum kondisyonun %0,2’si geri kazanılır. Etki her özel hareket için bir kez uygulanır.","rarity":"very_rare","effect":{"metric":"stamina_restore","operation":"fraction_of_maximum","value":0.002,"unit":"fraction"},"conditions":["Tek özel hareket en az iki farklı rakibe isabet ettiğinde.","Her özel hareket için bir kez."]},{"content_id":"chef_023","role_id":"cook","profession":"chef","ordinal":23,"title":"Çok Yönlü Savunmanın Beslenmesi","subtitle":"Farklı rakiplerden gelen baskıya hazırlanabilmek.","paragraph":"Birden fazla rakibin saldırısını karşılayan gladyatörlere ait notlar, Aşçıya yoğun savunmanın yükünü öğretir. Aşçı bu bilgiden yararlanarak kısa aralıklarla farklı yönlere savunma yapan gladyatörün gücünü destekleyen öğünler hazırlamayı öğrenir. Beş saniye içinde iki farklı rakibin saldırısı başarıyla bloklanırsa maksimum kondisyonun %0,4’ü geri kazanılır. Etki maç başına bir kez uygulanır.","effect_text":"Beş saniye içinde iki farklı rakibin saldırısı başarıyla bloklanırsa maksimum kondisyonun %0,4’ü geri kazanılır. Etki maç başına bir kez uygulanır.","rarity":"unique","effect":{"metric":"stamina_restore","operation":"fraction_of_maximum","value":0.004,"unit":"fraction"},"conditions":["Beş saniye içinde iki farklı rakibe karşı başarılı blok yapıldığında.","Maç başına bir kez."]},{"content_id":"chef_024","role_id":"cook","profession":"chef","ordinal":24,"title":"Birlikte Dövüşmenin Beslenmesi","subtitle":"Takım arkadaşına destek verirken harcanan gücü değerlendirmek.","paragraph":"Papirüs, bir rakibin yenilmesine birlikte katkıda bulunan gladyatörlerin dövüş kayıtlarını içerir. Aşçı, takım arkadaşına yardım ederken harcanan gücü gözetmeyi öğrenir ve bu bilgiyi gladyatörün mücadeleyi sürdürmesini destekleyen öğün hazırlığına aktarır. Maçtaki ilk asistte maksimum kondisyonun %0,2’si geri kazanılır. Etki maç başına bir kez uygulanır.","effect_text":"Maçtaki ilk asistte maksimum kondisyonun %0,2’si geri kazanılır.","rarity":"common","effect":{"metric":"stamina_restore","operation":"fraction_of_maximum","value":0.002,"unit":"fraction"},"conditions":["Oyunun asist olarak kaydettiği ilk katkıda.","Maç başına bir kez."]},{"content_id":"chef_025","role_id":"cook","profession":"chef","ordinal":25,"title":"Uzayan Mücadelenin Hazırlığı","subtitle":"Dövüş sürdükçe doğan ihtiyaçları önceden gözetebilmek.","paragraph":"Uzun süren arenaların notları, Aşçıya ilk hamlelerden sonra ortaya çıkan kondisyon ihtiyacını öğretir. Bu bilgiyle öğün hazırlayan Aşçı, gladyatörün mücadele uzadığında yeniden güç bulmasını destekleyen bir beslenme becerisi kazanır. Gladyatör hayattayken maçın ilk dakikası tamamlandığında maksimum kondisyonun %0,4’ü geri kazanılır. Etki maç başına bir kez uygulanır.","effect_text":"Gladyatör hayattayken maçın ilk dakikası tamamlandığında maksimum kondisyonun %0,4’ü geri kazanılır.","rarity":"common","effect":{"metric":"stamina_restore","operation":"fraction_of_maximum","value":0.004,"unit":"fraction"},"conditions":["Maç süresi 60 saniyeye ulaştığında.","Gladyatör hayattaysa.","Maç başına bir kez."]},{"content_id":"groom_001","role_id":"groom","profession":"groom","ordinal":1,"title":"Yarış Beslenmesinin Temelleri","subtitle":"Yemin yarış kondisyonuna katkısını anlayabilmek.","paragraph":"Papirüs, farklı beslenme düzenleriyle yarışa hazırlanan atların kayıtlarını karşılaştırır. Seyis, beslenmenin atın kullanabileceği kondisyon üzerindeki payını öğrenir ve günlük bakımını bu bilgiyi gözeterek düzenlemeyi kalıcı bir beceriye dönüştürür. Atın beslenmeden kazandığı maksimum yarış kondisyonu %0,4 artar.","effect_text":"Atın beslenmeden kazandığı maksimum yarış kondisyonu %0,4 artar.","rarity":"common","effect":{"metric":"nutrition_derived_maximum_race_stamina","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Beslenmenin sağladığı maksimum yarış kondisyonu katkısına uygulanır."]},{"content_id":"groom_002","role_id":"groom","profession":"groom","ordinal":2,"title":"Dayanıklılık Çalışmasının Düzeni","subtitle":"Antrenmanın kazandırdığı gelişimi değerlendirebilmek.","paragraph":"Atların kondisyon çalışmalarından alınmış notlar, Seyise egzersizin sağladığı gelişimi takip etmeyi öğretir. Seyis bu bilgiyi öğrenerek atın dayanıklılık çalışmasını daha bilinçli yönetir ve yapılan antrenmandan elde edilen kazanımı artırmayı öğrenir. Atın kondisyon antrenmanından kazandığı gelişim %0,4 artar.","effect_text":"Atın kondisyon antrenmanından kazandığı gelişim %0,4 artar.","rarity":"common","effect":{"metric":"horse_condition_training_gain","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["At kondisyon antrenmanı yaptığında."]},{"content_id":"groom_003","role_id":"groom","profession":"groom","ordinal":3,"title":"Yarış Sonrası Ahır Bakımı","subtitle":"Yarışın ardından dinlenmeyi doğru düzenleyebilmek.","paragraph":"Papirüs, piste çıkmış atların ahıra dönüşünden sonra tutulan bakım gözlemlerini içerir. Seyis, yarış sonrası dinlenmenin farklı aşamalarını okumayı ve atın kaybettiği kondisyonu toplamasını destekleyen bakım düzenini sürdürmeyi öğrenir. At yarıştan sonra ahırda dinlenirken kondisyonunu %0,4 daha hızlı toplar.","effect_text":"At yarıştan sonra ahırda dinlenirken kondisyonunu %0,4 daha hızlı toplar.","rarity":"common","effect":{"metric":"post_race_stable_stamina_recovery_rate","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Yarıştan sonra.","At ahırda dinlenirken."]},{"content_id":"groom_004","role_id":"groom","profession":"groom","ordinal":4,"title":"Çıkışın Hazırlığı","subtitle":"İlk hızlanmada harcanan gücü tanımak.","paragraph":"Yarış başlangıçlarının çizimleri ve yanlarına düşülen notlar, Seyise çıkış anının kondisyon yükünü öğretir. Öğrendiği hazırlık bilgisi, atın ilk hızlanma sırasında gücünü daha verimli kullanmasına katkıda bulunur. Yarış başındaki ilk hızlanma %0,4 daha az kondisyon harcatır.","effect_text":"Yarış başındaki ilk hızlanma %0,4 daha az kondisyon harcatır.","rarity":"common","effect":{"metric":"acceleration_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Yarış başındaki ilk hızlanmada."]},{"content_id":"groom_005","role_id":"groom","profession":"groom","ordinal":5,"title":"İlk Turun Temposu","subtitle":"Yarışa ölçülü bir güç dağılımıyla başlayabilmek.","paragraph":"Papirüs, ilk turdaki farklı hız seçimlerini atların yarış boyunca kalan gücüyle karşılaştırır. Seyis, yarışın başında orta tempoyu korumanın gerektirdiği hazırlığı öğrenir ve bu bilgi atın kondisyon kullanımına yansır. İlk turda hız göstergesi orta kademedeyken atın kondisyon tüketimi %0,4 azalır.","effect_text":"İlk turda hız göstergesi orta kademedeyken atın kondisyon tüketimi %0,4 azalır.","rarity":"common","effect":{"metric":"race_stamina_consumption","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["İlk turda.","Hız göstergesi orta kademedeyken."]},{"content_id":"groom_006","role_id":"groom","profession":"groom","ordinal":6,"title":"Düzlükte Dörtnal Bilgisi","subtitle":"Yüksek hızın sürdürülmesindeki yükü anlayabilmek.","paragraph":"Uzun düzlüklerden toplanan yarış gözlemleri, Seyise yüksek hızda kalmanın kondisyon maliyetini öğretir. Seyis bu bilgiyi öğrenerek atın dörtnalını sürdürmesine uygun hazırlık yapar ve düzlükte kullanılan gücün daha verimli değerlendirilmesini sağlar. Düzlükte en yüksek hız kademesini korurken kondisyon tüketimi %0,2 azalır.","effect_text":"Düzlükte en yüksek hız kademesini korurken kondisyon tüketimi %0,2 azalır.","rarity":"common","effect":{"metric":"race_stamina_consumption","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Düzlükte.","En yüksek hız kademesini korurken."]},{"content_id":"groom_007","role_id":"groom","profession":"groom","ordinal":7,"title":"Viraja Girişin Dengesi","subtitle":"Viraj öncesindeki temponun değerini görebilmek.","paragraph":"Papirüsteki dönüş çizimleri, farklı giriş hızlarının viraj boyunca kullanılan güçle ilişkisini anlatır. Seyis bu gözlemlerden orta hızla girilen viraja uygun hazırlığı öğrenir ve atın dönüş sırasında kondisyonunu daha dikkatli kullanmasını destekler. At viraja orta hız kademesinde girerse viraj boyunca %0,4 daha az kondisyon harcar.","effect_text":"At viraja orta hız kademesinde girerse viraj boyunca %0,4 daha az kondisyon harcar.","rarity":"common","effect":{"metric":"race_stamina_consumption","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["At viraja orta hız kademesinde girerse.","İlgili viraj boyunca."]},{"content_id":"groom_008","role_id":"groom","profession":"groom","ordinal":8,"title":"Viraj Çıkışının Hazırlığı","subtitle":"Dönüşten sonra yeniden hızlanmayı anlayabilmek.","paragraph":"Her virajın ardından başlayan hızlanmayı inceleyen notlar, Seyise bu geçişin kondisyon yükünü öğretir. Atın dönüş sonrası hız kazanmasına yönelik hazırlık bilgisi edinir ve bunu yarış boyunca uygulanan kalıcı bir beceriye dönüştürür. Her virajın çıkışındaki ilk hızlanma %0,4 daha az kondisyon harcatır.","effect_text":"Her virajın çıkışındaki ilk hızlanma %0,4 daha az kondisyon harcatır.","rarity":"common","effect":{"metric":"acceleration_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Her virajın çıkışındaki ilk hızlanmada."]},{"content_id":"groom_009","role_id":"groom","profession":"groom","ordinal":9,"title":"Sabit Temponun Korunması","subtitle":"Aynı ritimde ilerlemenin güce katkısını öğrenmek.","paragraph":"Papirüs, hızını sık değiştiren atlarla aynı tempoyu sürdüren atların gözlemlerini karşılaştırır. Seyis, yarışta bir hız kademesini korumanın gerektirdiği hazırlığı öğrenir ve bu bilgi atın gücünü daha ekonomik kullanmasına katkı sağlar. Aynı hız kademesinde beş saniye kalan at, o kademeyi koruduğu sürece %0,2 daha az kondisyon harcar.","effect_text":"Aynı hız kademesinde beş saniye kalan at, o kademeyi koruduğu sürece %0,2 daha az kondisyon harcar.","rarity":"common","effect":{"metric":"race_stamina_consumption","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Aynı hız kademesinde beş saniye kaldıktan sonra.","O hız kademesini koruduğu sürece."]},{"content_id":"groom_010","role_id":"groom","profession":"groom","ordinal":10,"title":"Düşük Tempoda Soluklanma","subtitle":"Yavaşlamayı toparlanma fırsatı olarak değerlendirebilmek.","paragraph":"Yarış içinde verilen düşük tempo araları üzerine tutulan kayıtlar, Seyise atın gücünü topladığı anları öğretir. Öğrendiği bakım ve hazırlık bilgisi, sürücünün yavaşladığı bölümden daha iyi toparlanarak çıkılmasına katkıda bulunur. Sürücü düşük hız kademesine geçtiğinde atın kondisyon yenilenme hızı %0,4 artar.","effect_text":"Sürücü düşük hız kademesine geçtiğinde atın kondisyon yenilenme hızı %0,4 artar.","rarity":"common","effect":{"metric":"race_stamina_regeneration_rate","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Sürücü düşük hız kademesine geçtiğinde."]},{"content_id":"groom_011","role_id":"groom","profession":"groom","ordinal":11,"title":"Sollama Öncesi Hazırlık","subtitle":"Kısa bir hızlanmanın doğru anını tanımak.","paragraph":"Papirüsteki yarış çizimleri, rakibine yaklaşan atların sollama için ayırdığı gücü anlatır. Seyis, yakından başlayan bir hızlanmaya uygun hazırlık bilgisini edinir ve atın geçiş sırasında harcadığı kondisyonu daha verimli kullanmasını destekler. At düzlükte önündeki rakibe bir araba boyu kadar yaklaşmışsa hızlanırken %0,4 daha az kondisyon harcar.","effect_text":"At düzlükte önündeki rakibe bir araba boyu kadar yaklaşmışsa hızlanırken %0,4 daha az kondisyon harcar.","rarity":"rare","effect":{"metric":"acceleration_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Düzlükte.","Önündeki rakibe bir araba boyu kadar yaklaşmışsa.","Hızlanırken."]},{"content_id":"groom_012","role_id":"groom","profession":"groom","ordinal":12,"title":"Çarpışmadan Sonra Yeniden Hızlanma","subtitle":"Kaybedilen tempoya dönerken gücü koruyabilmek.","paragraph":"Çarpışmayla temposu bozulan atların kayıtları, Seyise yeniden hızlanmanın taşıdığı yükü gösterir. Bu bilgiyi öğrenen Seyis, atın önceki hızına dönüşünü destekleyen hazırlıkta ustalaşır ve toparlanma sırasında kullanılan kondisyonu iyileştirir. Çarpışmayla hız kaybeden atın yeniden hızlanırken harcadığı kondisyon, çarpışma öncesi hızına ulaşana kadar %0,4 azalır.","effect_text":"Çarpışmayla hız kaybeden atın yeniden hızlanırken harcadığı kondisyon, çarpışma öncesi hızına ulaşana kadar %0,4 azalır.","rarity":"rare","effect":{"metric":"acceleration_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["At çarpışmayla hız kaybettiyse.","Yeniden hızlanırken.","Çarpışma öncesi hızına ulaşana kadar."]},{"content_id":"groom_013","role_id":"groom","profession":"groom","ordinal":13,"title":"Azalan Kondisyonu Gözetmek","subtitle":"Atın zorlandığı anlara önceden hazırlanabilmek.","paragraph":"Yarışın güç tüketen bölümlerine ait gözlemler, Seyise kondisyonu çok azalmış atların toparlanma ihtiyacını öğretir. Öğrendiği hazırlık bilgisi, atın düşük kondisyonla kaldığı anlarda yeniden güç toplamasını destekleyen bir beceriye dönüşür. Atın kondisyonu %25’in altındayken kondisyon yenilenme hızı %0,4 artar.","effect_text":"Atın kondisyonu %25’in altındayken kondisyon yenilenme hızı %0,4 artar.","rarity":"rare","effect":{"metric":"race_stamina_regeneration_rate","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Atın kondisyonu %25’in altındayken."]},{"content_id":"groom_014","role_id":"groom","profession":"groom","ordinal":14,"title":"Son Tura Güç Ayırmak","subtitle":"İlk turlardaki ölçünün değerini öğrenmek.","paragraph":"Beş turluk yarışların kayıtları, Seyise erken turlarda saklanan gücün son turdaki önemini anlatır. Seyis, kondisyonunu koruyarak ilerleyen atların son tura girişini destekleyen hazırlığı öğrenir ve bu bilgiyi yarış planına katar. At beşinci tura en az yarı kondisyonla girerse tur başında maksimum kondisyonunun %0,4’ünü geri kazanır.","effect_text":"At beşinci tura en az yarı kondisyonla girerse tur başında maksimum kondisyonunun %0,4’ünü geri kazanır.","rarity":"unique","effect":{"metric":"race_stamina_restore","operation":"fraction_of_maximum","value":0.004,"unit":"fraction"},"conditions":["Beşinci turun başlangıcında.","At tura en az yarı kondisyonla girerse."]},{"content_id":"groom_015","role_id":"groom","profession":"groom","ordinal":15,"title":"Finiş Dörtnalının Hazırlığı","subtitle":"Son düzlükte kalan gücü değerlendirebilmek.","paragraph":"Papirüs, beşinci turun son düzlüğüne giren atların hız ve kondisyon kayıtlarını bir araya getirir. Seyis, finişe en yüksek tempoda uzanmak için gereken hazırlık bilgisini öğrenir ve atın son bölümde kullandığı gücü destekler. Beşinci turun son düzlüğünde en yüksek hız kademesindeyken at %0,4 daha az kondisyon harcar.","effect_text":"Beşinci turun son düzlüğünde en yüksek hız kademesindeyken at %0,4 daha az kondisyon harcar.","rarity":"rare","effect":{"metric":"race_stamina_consumption","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Beşinci turun son düzlüğünde.","En yüksek hız kademesindeyken."]},{"content_id":"groom_016","role_id":"groom","profession":"groom","ordinal":16,"title":"Hızlanmanın Hareket Bilgisi","subtitle":"Atın adımlarını artan tempoya hazırlayabilmek.","paragraph":"Papirüs, farklı hız kademeleri arasında ilerleyen atların adım kayıtlarını içerir. Seyis, hız kazanırken hareketin nasıl düzenlendiğini öğrenir ve bu bilgiyi yarışa hazırlık sırasında kullanarak atın tempoyu daha çabuk artırmasını destekler. Atın yarış içindeki hızlanma hızı %0,2 artar.","effect_text":"Atın yarış içindeki hızlanma hızı %0,2 artar.","rarity":"rare","effect":{"metric":"race_acceleration_rate","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":["At yarış içinde hızlanırken."]},{"content_id":"groom_017","role_id":"groom","profession":"groom","ordinal":17,"title":"Virajda Hızı Taşımak","subtitle":"Dönüş sırasında kaybedilen tempoyu anlayabilmek.","paragraph":"Dönüş çizimleriyle karşılaştırılan yarış kayıtları, Seyise virajda hızın nerede kaybedildiğini öğretir. Seyis bu bilgiyi öğrenerek atın dönüş hareketine yönelik hazırlığını geliştirir ve yarış temposunun viraj boyunca daha iyi korunmasına katkı sunar. Viraj dönüşünden kaynaklanan hız kaybı %0,4 azalır.","effect_text":"Viraj dönüşünden kaynaklanan hız kaybı %0,4 azalır.","rarity":"rare","effect":{"metric":"turning_speed_loss","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Viraj dönüşünden kaynaklanan hız kaybına uygulanır."]},{"content_id":"groom_018","role_id":"groom","profession":"groom","ordinal":18,"title":"Temas Anında Denge","subtitle":"Çarpışmanın yarış temposuna etkisini okuyabilmek.","paragraph":"Papirüs, yarış sırasında temas yaşayan atların hız kayıtlarını ve denge gözlemlerini bir araya getirir. Seyis, temasa hazırlığın önemini öğrenir ve bu bilgi atın bir çarpışma sırasında sahip olduğu tempoyu daha iyi korumasını destekler. Çarpışmadan kaynaklanan hız kaybı %0,4 azalır.","effect_text":"Çarpışmadan kaynaklanan hız kaybı %0,4 azalır.","rarity":"very_rare","effect":{"metric":"collision_speed_loss","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Yarış içindeki çarpışmadan kaynaklanan hız kaybına uygulanır."]},{"content_id":"groom_019","role_id":"groom","profession":"groom","ordinal":19,"title":"Virajda Yön Değiştirme","subtitle":"Dönüş komutuna uyum sağlayan hareketi anlayabilmek.","paragraph":"Farklı viraj çizgilerini inceleyen notlar, Seyise atın yön değiştirme hareketine nasıl hazırlanacağını öğretir. Bu bilgiyi öğrenen Seyis, yarışta dönüş sırasında gereken uyumu destekleyen bir beceri kazanır ve bunu günlük hazırlığına aktarır. Virajlarda atın yön değiştirme hızı %0,2 artar.","effect_text":"Virajlarda atın yön değiştirme hızı %0,2 artar.","rarity":"rare","effect":{"metric":"turning_direction_change_rate","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":["At yarışta viraj dönerken."]},{"content_id":"groom_020","role_id":"groom","profession":"groom","ordinal":20,"title":"Hız Çalışmasının Esasları","subtitle":"Sürat antrenmanından elde edilen gelişimi değerlendirebilmek.","paragraph":"Papirüs, sürat çalışmalarındaki ilerlemeyi atların hazırlık kayıtlarıyla birlikte ele alır. Seyis bu bilgiyi öğrenerek hız antrenmanının katkısını takip etmeyi ve yapılan çalışmadan daha fazla gelişim elde edilmesini desteklemeyi kalıcı bir beceriye dönüştürür. Atın hız antrenmanından kazandığı gelişim %0,4 artar.","effect_text":"Atın hız antrenmanından kazandığı gelişim %0,4 artar.","rarity":"common","effect":{"metric":"horse_speed_training_gain","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["At hız antrenmanı yaptığında."]},{"content_id":"groom_021","role_id":"groom","profession":"groom","ordinal":21,"title":"Çalışma Yükünü Gözetmek","subtitle":"Antrenmanın yorgunluğunu bilinçli yönetebilmek.","paragraph":"Atların çalışma sonrası durumlarını karşılaştıran kayıtlar, Seyise antrenmanın yarattığı yorgunluğu değerlendirmeyi öğretir. Öğrendiği düzenleme bilgisiyle atın çalışmasını daha dikkatli yönetir ve hazırlık sırasında biriken yorgunluğun azaltılmasına bilinçli bir bakım anlayışıyla katkıda bulunur. Atın antrenmandan kazandığı yorgunluk %0,4 azalır.","effect_text":"Atın antrenmandan kazandığı yorgunluk %0,4 azalır.","rarity":"common","effect":{"metric":"horse_training_fatigue_gain","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Atın tamamladığı antrenmandan doğan yorgunluğa uygulanır."]},{"content_id":"groom_022","role_id":"groom","profession":"groom","ordinal":22,"title":"Çıkışta Hız Kazanmak","subtitle":"Başlangıcın kısa süresini daha iyi değerlendirebilmek.","paragraph":"Papirüs, yarışın ilk adımlarına ayrılmış ayrıntılı gözlemler taşır. Seyis, çıkış anında atın hareketini hız kazanmaya hazırlayan bilgiyi öğrenir ve başlangıçtaki kısa aralığı daha iyi kullanmasını sağlayan bir beceri edinir. Yarış başındaki ilk hızlanmanın hızı %0,4 artar.","effect_text":"Yarış başındaki ilk hızlanmanın hızı %0,4 artar.","rarity":"very_rare","effect":{"metric":"race_acceleration_rate","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Yarış başındaki ilk hızlanmada."]},{"content_id":"groom_023","role_id":"groom","profession":"groom","ordinal":23,"title":"Son Turun Sürati","subtitle":"Bitişe yaklaşırken tempoyu yükseltmeye hazırlanabilmek.","paragraph":"Beşinci tura ait yarış kayıtları, Seyise finişe yaklaşırken atın süratini koruma ve kullanma bilgisini öğretir. Bu bilgiyi hazırlığına katan Seyis, son turda ulaşılabilen hızın artırılmasına pasif olarak katkı sunar. Beşinci turda atın ulaşabildiği maksimum hız %0,2 artar.","effect_text":"Beşinci turda atın ulaşabildiği maksimum hız %0,2 artar.","rarity":"very_rare","effect":{"metric":"maximum_race_speed","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":["Yarışın beşinci turunda."]},{"content_id":"groom_024","role_id":"groom","profession":"groom","ordinal":24,"title":"Yarış Yükünü Hafifletmek","subtitle":"Pistteki çabanın ahıra taşınan etkisini anlayabilmek.","paragraph":"Papirüs, tamamlanan yarışların ardından atlarda biriken yorgunluğu kayıt altına alır. Seyis, yarış öncesi hazırlık ile yarış sonrası durum arasındaki ilişkiyi öğrenir ve atın müsabakadan daha az yorgun dönmesini destekleyen bilgi kazanır. Yarış sonunda ata eklenen yorgunluk %0,4 azalır.","effect_text":"Yarış sonunda ata eklenen yorgunluk %0,4 azalır.","rarity":"rare","effect":{"metric":"horse_race_fatigue_gain","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Yarış tamamlandığında ata eklenecek yorgunluğa uygulanır."]},{"content_id":"groom_025","role_id":"groom","profession":"groom","ordinal":25,"title":"Son Güçle Hızlanma","subtitle":"Son turda azalan kondisyonu dikkatle kullanabilmek.","paragraph":"Yarışın son turunda gücü azalan atların gözlemleri, Seyise yeniden hız kazanırken kalan kondisyonu gözetmeyi öğretir. Seyis bu ileri hazırlık bilgisiyle atın son bölümdeki hızlanmasına katkıda bulunur ve kalan gücün daha verimli kullanılmasını destekler. Beşinci turda kondisyon %25’in altındayken hızlanmanın kondisyon tüketimi %0,4 azalır.","effect_text":"Beşinci turda kondisyon %25’in altındayken hızlanmanın kondisyon tüketimi %0,4 azalır.","rarity":"very_rare","effect":{"metric":"acceleration_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Yarışın beşinci turunda.","Atın kondisyonu %25’in altındayken.","At hızlanırken."]},{"content_id":"guard_001","role_id":"guard","profession":"guard","ordinal":1,"title":"Kervan Savunmasının Esasları","subtitle":"Bir yolculuğun güvenliğini savunma düzeninden okuyabilmek.","paragraph":"Papirüs, kervanın çevresinde kurulan savunma düzenini ve muhafızların birbirini nasıl desteklediğini anlatır. Muhafız bu bilgiyi öğrenerek saldırı karşısında ekibin gücünü daha iyi kullanmayı kavrar. Öğrendiği bilginin kervan savunmasına yansımasıyla **saldırı gücüne +%0,01 pasif bonus kazandırır**.","effect_text":"Kervan savunması saldırı bonusu +%0,01.","rarity":"common","effect":{"metric":"caravan_defense_attack","operation":"relative_increase","value":0.0001,"unit":"fraction"},"conditions":["Kervan savunması","Kervan sahibinin öğrenilmiş bonusu"]},{"content_id":"guard_002","role_id":"guard","profession":"guard","ordinal":2,"title":"Okçunun Görüş Hattı","subtitle":"Bir okun hedefe ulaşacağı hattı değerlendirebilmek.","paragraph":"Yük arabalarının ve savunma noktalarının çevresine çizilmiş görüş hatları, Muhafıza okçuların ateş düzenini değerlendirmeyi öğretir. Bu bilgiyi işçilerin savunmasına aktararak ok atışlarının etkisini artırır. Kervan savunmasında silahlı işçilerin **okla verdiği hasar %0,2 artar**.","effect_text":"Silahlı işçilerin ok hasarı +%0,2.","rarity":"common","effect":{"metric":"worker_arrow_damage","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Silahlı işçi","Ok isabeti"]},{"content_id":"guard_003","role_id":"guard","profession":"guard","ordinal":3,"title":"Yakın Muharebede Güç Kullanımı","subtitle":"Her savuruşta harcanan gücü ölçebilmeyi öğrenmek.","paragraph":"Dar bir savunma alanında yapılan vuruşların çizimleri, Muhafıza gereksiz hareketlerin ekibi nasıl yorduğunu gösterir. Öğrendiği ölçülü hareket bilgisi, kervanı koruyan gladyatörlerin yakın dövüşüne katkı sağlar. Savunma sırasında gladyatörlerin **normal yakın dövüş saldırılarındaki kondisyon tüketimi %0,2 azalır**.","effect_text":"Savunmacı gladyatörlerin normal yakın dövüş saldırısında kondisyon tüketimi −%0,2.","rarity":"common","effect":{"metric":"escort_normal_melee_stamina_cost","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Normal yakın dövüş saldırısı"]},{"content_id":"guard_004","role_id":"guard","profession":"guard","ordinal":4,"title":"Mızrağın Atış Hazırlığı","subtitle":"Atışa ayrılan gücü hareketin bütünü içinde değerlendirebilmek.","paragraph":"Papirüsteki mızrak atışları, hazırlık duruşundan silahın elden çıkışına kadar izlenen hareketi anlatır. Muhafız bu bilgiden yararlanarak savunmacıların atış sırasında güçlerini daha dikkatli kullanmasını sağlar. Kervanı savunan gladyatörlerin **mızrak fırlatma özel hareketindeki kondisyon tüketimi %0,4 azalır**.","effect_text":"Mızrak fırlatmada kondisyon tüketimi −%0,4.","rarity":"rare","effect":{"metric":"escort_spear_throw_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Mızrak fırlatma özel hareketi"]},{"content_id":"guard_005","role_id":"guard","profession":"guard","ordinal":5,"title":"Tridentin Atış Dengesi","subtitle":"Ağır bir silahın savruluşunda dengeyi korumayı öğrenmek.","paragraph":"Tridentin ağırlık dağılımını hareket çizimleriyle anlatan bu papirüs, Muhafıza atış sırasında dengeli güç kullanımını öğretir. Bu bilgi, savunma ekibindeki trident kullanıcılarının hazırlığına yansır. Kervanı savunan gladyatörlerin **trident fırlatma özel hareketindeki kondisyon tüketimi %0,4 azalır**.","effect_text":"Trident fırlatmada kondisyon tüketimi −%0,4.","rarity":"rare","effect":{"metric":"escort_trident_throw_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Trident fırlatma özel hareketi"]},{"content_id":"guard_006","role_id":"guard","profession":"guard","ordinal":6,"title":"Kalkanın Arkasında Beklemek","subtitle":"Darbeyi karşılarken harcanan gücü yönetebilmek.","paragraph":"Birbirini izleyen darbeleri karşılayan kalkanların çizimleri, Muhafıza savunma duruşunu sürdürmenin inceliklerini öğretir. Öğrenilen bilgi, savunma ekibinin darbeyi karşılarken daha ölçülü güç kullanmasına yardım eder. Kervanı savunan gladyatörlerin **başarılı bloklarında harcanan kondisyon %0,2 azalır**.","effect_text":"Başarılı bloklarda kondisyon tüketimi −%0,2.","rarity":"common","effect":{"metric":"escort_successful_block_stamina_cost","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Başarılı kalkan bloğu"]},{"content_id":"guard_007","role_id":"guard","profession":"guard","ordinal":7,"title":"Kalkanla Mesafe Açmak","subtitle":"Sıkışan savunmada alan kazanmanın tekniğini öğrenmek.","paragraph":"Papirüs, kalkanla yapılan itişin ayak duruşu ve gövde hareketiyle ilişkisini gösterir. Muhafız, bu hareketi savunma ekibine daha verimli aktaracak bilgiyi edinir. Kervanı savunan gladyatörlerin **kalkanla itip yere düşürme özel hareketindeki kondisyon tüketimi %0,4 azalır**.","effect_text":"Kalkan itişi özel hareketinde kondisyon tüketimi −%0,4.","rarity":"rare","effect":{"metric":"escort_shield_push_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Kalkan itişi özel hareketi"]},{"content_id":"guard_008","role_id":"guard","profession":"guard","ordinal":8,"title":"Yük Arabasının Çevresinde Kaçınma","subtitle":"Dar alandaki kaçış hareketini dengeyle tamamlayabilmek.","paragraph":"Yük arabasının yanında uygulanan kaçınma çizimleri, Muhafıza dönme ve yeniden doğrulma sırasında güç kaybını azaltmayı öğretir. Edindiği bilgi savunmacıların çevik hareketlerine yansır. Kervan savunması boyunca gladyatörlerin **yuvarlanma hareketinde harcadığı kondisyon %0,2 azalır**.","effect_text":"Yuvarlanmada kondisyon tüketimi −%0,2.","rarity":"common","effect":{"metric":"escort_roll_stamina_cost","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Yuvarlanma"]},{"content_id":"guard_009","role_id":"guard","profession":"guard","ordinal":9,"title":"Savunma Noktaları Arasında Koşu","subtitle":"Yetişilecek mesafeye göre gücü ayarlayabilmek.","paragraph":"Papirüsteki savunma çizimleri, arabanın farklı yanları arasında koşarken izlenen hareketleri karşılaştırır. Muhafız, bir noktadan diğerine yetişirken ekibin gücünü verimli kullanmasını sağlayan bilgiyi öğrenir. Kervanı savunan gladyatörlerin **koşu sırasında harcadığı kondisyon %0,2 azalır**.","effect_text":"Koşuda kondisyon tüketimi −%0,2.","rarity":"common","effect":{"metric":"escort_running_stamina_cost","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Koşu"]},{"content_id":"guard_010","role_id":"guard","profession":"guard","ordinal":10,"title":"Çatışma Arasında Soluklanmak","subtitle":"Hareketler arasındaki dinlenme fırsatını değerlendirebilmek.","paragraph":"Bir savunmanın farklı anlarına ait notlar, Muhafıza ekibin ne zaman soluklanabildiğini gözlemlemeyi öğretir. Bu bilgi, savunmacıların çatışma boyunca güçlerini yeniden toplamasına katkı sağlar. Kervan savunması sırasında gladyatörlerin **kondisyon yenilenme hızı %0,2 artar**.","effect_text":"Savunmacı gladyatörlerin kondisyon yenilenme hızı +%0,2.","rarity":"common","effect":{"metric":"escort_stamina_regeneration","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Mevcut kondisyon yenilenmesi çalışırken"]},{"content_id":"guard_011","role_id":"guard","profession":"guard","ordinal":11,"title":"Tükenen Gücü Yeniden Toplamak","subtitle":"Yorgun bir savunmacının toparlanma ihtiyacını okuyabilmek.","paragraph":"Uzayan çatışmalara ait gözlemler, Muhafıza gücü azalan savunmacıların hareketlerini değerlendirmeyi öğretir. Bu bilgiyi öğrenmesi, ekibin tükenmeye yaklaştığı anlarda toparlanmasına pasif destek sağlar. Kervan savunmasında kondisyonu %25'in altına inen gladyatörün **kondisyon yenilenme hızı %0,4 artar**.","effect_text":"Kondisyon %25'in altındayken yenilenme hızı +%0,4.","rarity":"very_rare","effect":{"metric":"escort_low_stamina_regeneration","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Mevcut kondisyon / maksimum kondisyon < 0.25","Mevcut kondisyon yenilenmesi çalışırken"]},{"content_id":"guard_012","role_id":"guard","profession":"guard","ordinal":12,"title":"Yaralı Savunmacıyı Korumak","subtitle":"Gücü azalan bir yoldaşın savunma ihtiyacını fark edebilmek.","paragraph":"Papirüs, yaralandıktan sonra savunmayı sürdüren gladyatörlere ait konum ve duruş notları içerir. Muhafız, ekibin tehlikeye açık anlarını daha dikkatli değerlendirmeyi öğrenir. Kervan savunmasında canı %25'in altına düşen savunmacı gladyatörün **aldığı hasar %0,4 azalır**.","effect_text":"Canı %25'in altındaki savunmacı gladyatörün aldığı hasar −%0,4.","rarity":"very_rare","effect":{"metric":"escort_low_health_incoming_damage","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Mevcut can / maksimum can < 0.25"]},{"content_id":"guard_013","role_id":"guard","profession":"guard","ordinal":13,"title":"İşçileri Ok Ateşinden Korumak","subtitle":"Uzak saldırıların yönüne göre korumayı değerlendirebilmek.","paragraph":"Yol üzerindeki saldırı noktalarını gösteren çizimler, Muhafıza ok ateşinin işçilere hangi açılardan ulaştığını öğretir. Bu bilgi, çalışanları koruyan savunma düzenine yansır. Kervan savunmasında işçilerin **düşman oklarından aldığı hasar %0,4 azalır**.","effect_text":"İşçilerin düşman oklarından aldığı hasar −%0,4.","rarity":"common","effect":{"metric":"worker_incoming_arrow_damage","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Hedef işçi","Düşman ok isabeti"]},{"content_id":"guard_014","role_id":"guard","profession":"guard","ordinal":14,"title":"İşçinin Yanında Savunma","subtitle":"Yakına ulaşan saldırgana karşı koruma düzenini anlayabilmek.","paragraph":"Papirüs, düşmanın işçilere kadar yaklaştığı çatışmalarda tutulan savunma notlarını içerir. Muhafız, çalışanların yakın saldırılara açık kaldığı durumları değerlendirmeyi ve korumayı buna göre hazırlamayı öğrenir. Kervan savunmasında işçilerin **yakın dövüş saldırılarından aldığı hasar %0,2 azalır**.","effect_text":"İşçilerin yakın dövüş saldırılarından aldığı hasar −%0,2.","rarity":"common","effect":{"metric":"worker_incoming_melee_damage","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Hedef işçi","Yakın dövüş isabeti"]},{"content_id":"guard_015","role_id":"guard","profession":"guard","ordinal":15,"title":"Arabanın Açıkta Kalan Yüzü","subtitle":"Yük arabasının uzak saldırılara açık noktalarını tanıyabilmek.","paragraph":"Arabanın farklı yönlerinden yapılmış çizimler, Muhafıza okların yük ve gövde üzerinde ulaştığı bölgeleri öğretir. Bu bilgiyi öğrenmesi, kervanın korunmasına ilişkin hazırlığı geliştirir. Savunma çatışması boyunca yük arabasının **düşman oklarından aldığı hasar %0,4 azalır**.","effect_text":"Yük arabasının düşman oklarından aldığı hasar −%0,4.","rarity":"rare","effect":{"metric":"cart_incoming_arrow_damage","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Hedef yük arabası","Düşman ok isabeti"]},{"content_id":"guard_016","role_id":"guard","profession":"guard","ordinal":16,"title":"Araba Çevresindeki Savunma Hattı","subtitle":"Yakın saldırıların yüke ulaşmasını azaltacak düzeni öğrenmek.","paragraph":"Papirüs, yük arabasına yaklaşan saldırganların kullandığı yolları ve bu yolların çevresindeki savunma duruşlarını karşılaştırır. Muhafız, arabanın yakın savunmasını daha bilinçli değerlendirme becerisi kazanır. Kervan çatışmasında yük arabasının **yakın dövüş saldırılarından aldığı hasar %0,2 azalır**.","effect_text":"Yük arabasının yakın dövüş saldırılarından aldığı hasar −%0,2.","rarity":"common","effect":{"metric":"cart_incoming_melee_damage","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Hedef yük arabası","Yakın dövüş isabeti"]},{"content_id":"guard_017","role_id":"guard","profession":"guard","ordinal":17,"title":"Miğferin Koruduğu Açı","subtitle":"Baş korumasını savunma duruşuyla birlikte değerlendirmek.","paragraph":"Farklı savunma duruşlarında çizilmiş miğferler, Muhafıza başın korunmasının yön ve hareketle ilişkisini öğretir. Bu bilgi kervanı savunan gladyatörlerin koruyucu hazırlığına aktarılır. Takılı miğferin koruduğu baş bölgesine gelen **hasar kervan savunmasında %0,2 azalır**.","effect_text":"Takılı miğferin koruduğu baş bölgesine gelen hasar −%0,2.","rarity":"common","effect":{"metric":"escort_helmet_protected_head_damage","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Miğfer takılı","İsabet miğferin koruduğu baş bölgesinde"]},{"content_id":"guard_018","role_id":"guard","profession":"guard","ordinal":18,"title":"Göğüs Zırhını Kullanma Bilgisi","subtitle":"Gövde korumasını hareket içinde değerlendirebilmek.","paragraph":"Papirüs, savunma sırasında gövdenin yönünü değiştiren gladyatörlerin çizimlerini içerir. Muhafız, göğüs zırhının koruduğu alanı duruşla birlikte okumayı öğrenir. Bu öğrenimin pasif etkisiyle kervan savunmasında takılı göğüs zırhının koruduğu bölgeye gelen **hasar %0,2 azalır**.","effect_text":"Takılı göğüs zırhının koruduğu bölgeye gelen hasar −%0,2.","rarity":"common","effect":{"metric":"escort_armor_protected_torso_damage","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Göğüs zırhı takılı","İsabet zırhın koruduğu bölgede"]},{"content_id":"guard_019","role_id":"guard","profession":"guard","ordinal":19,"title":"Silah Kolunu Koruma","subtitle":"Savuruş sırasında açılan kolun korunmasını öğrenmek.","paragraph":"Kılıç, mızrak ve kalkan taşıyan kolların çizimleri, Muhafıza savunma hareketlerinin bıraktığı açıklıkları gösterir. Edindiği bilgi, kol koruyucusunun kullanıldığı hazırlığa yansır. Kervan savunmasında takılı kolluğun koruduğu kola gelen **hasar %0,2 azalır**.","effect_text":"Takılı kolluğun koruduğu kola gelen hasar −%0,2.","rarity":"rare","effect":{"metric":"escort_manica_protected_arm_damage","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Kolluk takılı","İsabet kolluğun koruduğu kolda"]},{"content_id":"guard_020","role_id":"guard","profession":"guard","ordinal":20,"title":"Ayakta Kalan Savunma","subtitle":"Alt beden korumasını duruşla birlikte okuyabilmek.","paragraph":"Arabanın çevresinde savunma yapan gladyatörlerin ayak duruşları, bacak korumasının nasıl değerlendirildiğine ilişkin notlarla anlatılır. Muhafız bu bilgiyi öğrenerek ekibin koruyucu hazırlığını geliştirir. Kervan savunmasında takılı bacaklığın koruduğu bölgeye gelen **hasar %0,2 azalır**.","effect_text":"Takılı bacaklığın koruduğu bölgeye gelen hasar −%0,2.","rarity":"rare","effect":{"metric":"escort_greave_protected_leg_damage","operation":"relative_decrease","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Bacaklık takılı","İsabet bacaklığın koruduğu bölgede"]},{"content_id":"guard_021","role_id":"guard","profession":"guard","ordinal":21,"title":"İlk Saldırıyı Karşılama","subtitle":"Çatışmanın başlangıcında savunmayı birlikte kurabilmek.","paragraph":"İlk baskın anına ait kayıtlar, Muhafıza ekibin başlangıçtaki hareketlerini birbirine bağlamayı öğretir. Savunmanın kurulmasına ilişkin bu bilgi, ilk saldırıya verilen karşılığa güç kazandırır. Kervan savunmasının **birinci dalgasında savunmacı gladyatörlerin verdiği hasar %0,2 artar**.","effect_text":"Birinci dalgada savunmacı gladyatörlerin verdiği hasar +%0,2.","rarity":"rare","effect":{"metric":"escort_first_wave_damage","operation":"relative_increase","value":0.002,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Dalga numarası 1"]},{"content_id":"guard_022","role_id":"guard","profession":"guard","ordinal":22,"title":"Son Dalgaya Hazırlık","subtitle":"Uzayan savunmada son karşılaşmanın düzenini öğrenmek.","paragraph":"Beş dalgalık savunmaların son anlarını anlatan notlar, Muhafıza ekibin son saldırıya nasıl hazırlandığını gösterir. Bu bilgi, savunmanın son bölümünde güç kullanımını daha iyi değerlendirmesini sağlar. Kervan savunmasının **beşinci dalgasında savunmacı gladyatörlerin verdiği hasar %0,4 artar**.","effect_text":"Beşinci dalgada savunmacı gladyatörlerin verdiği hasar +%0,4.","rarity":"unique","effect":{"metric":"escort_fifth_wave_damage","operation":"relative_increase","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Dalga numarası 5"]},{"content_id":"guard_023","role_id":"guard","profession":"guard","ordinal":23,"title":"Ağla Yaklaşmayı Durdurmak","subtitle":"Yaklaşan saldırganı durduracak hareketi ölçülü kullanabilmek.","paragraph":"Papirüs, arabanın yakınında atılan ağların hazırlık hareketlerini çizimlerle anlatır. Muhafız, ağ kullanıcısının hareketini daha verimli değerlendirmesini sağlayan bilgiyi öğrenir. Kervanı savunan gladyatörlerin **ağ atma özel hareketinde harcadığı kondisyon %0,4 azalır**.","effect_text":"Ağ atma özel hareketinde kondisyon tüketimi −%0,4.","rarity":"rare","effect":{"metric":"escort_net_throw_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Ağ atma özel hareketi"]},{"content_id":"guard_024","role_id":"guard","profession":"guard","ordinal":24,"title":"Kırbaçla Mesafeyi Yönetmek","subtitle":"Çekme hareketinin gücünü ve zamanını kavrayabilmek.","paragraph":"Kırbaçla yapılan çekişleri gösteren çizimler, Muhafıza bu hareket sırasında bedenin nasıl güç harcadığını öğretir. Öğrendiği bilgi, kervan savunmasındaki kırbaç kullanıcılarının hazırlığına yansır. Savunmacı gladyatörlerin **kırbaçla çekme özel hareketindeki kondisyon tüketimi %0,4 azalır**.","effect_text":"Kırbaçla çekme özel hareketinde kondisyon tüketimi −%0,4.","rarity":"very_rare","effect":{"metric":"escort_whip_pull_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Kırbaçla çekme özel hareketi"]},{"content_id":"guard_025","role_id":"guard","profession":"guard","ordinal":25,"title":"Kalkan Kırmanın Hazırlığı","subtitle":"Sert bir savunmayı aşarken gücü doğru kullanabilmek.","paragraph":"Gürz ve çekiçle yapılan özel vuruşların hareket çizimleri, Muhafıza darbenin hazırlığı ile harcanan güç arasındaki ilişkiyi öğretir. Bu bilgi, kervanı koruyan ekibin güçlü hamlelerine katkı sağlar. Savunmacı gladyatörlerin **gürz veya çekiçle kalkan kırma özel hareketindeki kondisyon tüketimi %0,4 azalır**.","effect_text":"Gürz veya çekiçle kalkan kırma özel hareketinde kondisyon tüketimi −%0,4.","rarity":"very_rare","effect":{"metric":"escort_shield_break_stamina_cost","operation":"relative_decrease","value":0.004,"unit":"fraction"},"conditions":["Kervan savunması","Savunmacı gladyatör","Gürz veya çekiç","Kalkan kırma özel hareketi"]},{"content_id":"blacksmith_general_001","role_id":"smith","profession":"blacksmith","ordinal":1,"title":"Geliştirmenin Temelleri","subtitle":"Bir ekipmanın bir sonraki kademeye nasıl hazırlandığını öğrenmek.","paragraph":"Papirüs, geliştirme öncesinde yüzeyin ve bağlantıların nasıl değerlendirildiğini anlatır. Demirci, her ekipmanda uygulayabileceği bir hazırlık bilgisi edinir. Bütün uygun itemlerde **+ basma başarı ihtimali +0,2 yüzde puan artar**.","effect_text":"Bütün uygun itemlerde + basma başarı ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"upgrade_success_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"general"}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Geçerli bir + geliştirme denemesi."]},{"content_id":"blacksmith_general_002","role_id":"smith","profession":"blacksmith","ordinal":2,"title":"İlk Kademelerin Ölçüsü","subtitle":"Başlangıç işçiliğinin küçük ayrıntılarını okuyabilmek.","paragraph":"İlk geliştirmelere ait çizimler, küçük bir değişimin ekipmanın bütününe nasıl yayıldığını gösterir. Demirci, başlangıç kademelerinde uyguladığı işlemi daha dikkatli hazırlamayı öğrenir. Hedef seviye **+1–+4 arasındaysa + basma başarı ihtimali +0,2 yüzde puan artar**.","effect_text":"Hedef seviye +1–+4 arasındaysa + basma başarı ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"upgrade_success_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional"}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Hedef + seviyesi 1 ile 4 arasındadır."]},{"content_id":"blacksmith_general_003","role_id":"smith","profession":"blacksmith","ordinal":3,"title":"Orta Kademelerin Dengesi","subtitle":"Önceki işçiliğin üzerine yeni bir kademe kurabilmek.","paragraph":"Papirüs, birkaç kez geliştirilmiş ekipmanların yüzey ve birleşim izlerini karşılaştırır. Demirci, mevcut işçiliği koruyarak bir sonraki kademeye hazırlanmanın inceliklerini öğrenir. Hedef seviye **+5–+8 arasındaysa + basma başarı ihtimali +0,2 yüzde puan artar**.","effect_text":"Hedef seviye +5–+8 arasındaysa + basma başarı ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"upgrade_success_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional"}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Hedef + seviyesi 5 ile 8 arasındadır."]},{"content_id":"blacksmith_general_004","role_id":"smith","profession":"blacksmith","ordinal":4,"title":"Yüksek Kademelerin İnceliği","subtitle":"Usta işi ekipmanın hassasiyetini anlayabilmek.","paragraph":"Yüksek seviyeli ekipmanlara düşülmüş işçilik notları, ilerleyen her kademede hangi ayrıntıların önem kazandığını anlatır. Demirci, bu hassas hazırlığı kalıcı bir meslek bilgisine dönüştürür. Hedef seviye **+9 veya üzerindeyse + basma başarı ihtimali +0,2 yüzde puan artar**.","effect_text":"Hedef seviye +9 veya üzerindeyse + basma başarı ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"upgrade_success_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional"}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Hedef + seviyesi en az 9dur."]},{"content_id":"blacksmith_general_005","role_id":"smith","profession":"blacksmith","ordinal":5,"title":"Başarılı İşçiliğin Devamı","subtitle":"İşe yarayan uygulamanın izini bir sonraki denemeye taşımak.","paragraph":"Papirüs, başarılı bir geliştirmenin ardından ekipmanda kalan işçilik izlerinin nasıl okunacağını öğretir. Demirci, aynı parça üzerindeki sonraki çalışmasını bu gözleme göre hazırlar. Aynı itemdeki serinin önceki + basışı başarılıysa **bir sonraki + basmanın başarı ihtimali +0,2 yüzde puan artar**.","effect_text":"Aynı itemdeki serinin önceki + basışı başarılıysa bir sonraki + basmanın başarı ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"upgrade_success_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional"}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve upgrade serisinin son tamamlanan denemesi başarılıdır."]},{"content_id":"blacksmith_general_006","role_id":"smith","profession":"blacksmith","ordinal":6,"title":"Tekrardan Doğan Ustalık","subtitle":"Aynı parçayla çalışırken biriken gözlemi değerlendirmek.","paragraph":"Art arda tutulmuş geliştirme notları, Demirciye aynı ekipmanın her denemede verdiği işaretleri karşılaştırmayı öğretir. Tekrar edilen çalışma, parçayı daha iyi tanımasını sağlar. Aynı iteme arka arkaya + basarken **üçüncü ve sonraki denemelerin başarı ihtimali +0,2 yüzde puan artar**.","effect_text":"Aynı iteme arka arkaya + basarken üçüncü ve sonraki denemelerin başarı ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"upgrade_success_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional"}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve upgrade serisinde işlem öncesi en az 2 tamamlanmış deneme vardır."]},{"content_id":"blacksmith_general_007","role_id":"smith","profession":"blacksmith","ordinal":7,"title":"Beşinci Denemenin Disiplini","subtitle":"Uzayan çalışmada biriken bilgiyi kullanabilmek.","paragraph":"Papirüs, aynı ekipman üzerinde sürdürülen uzun çalışmaların karşılaştırmalı kayıtlarını içerir. Demirci, önceki denemelerden edindiği bilgiyi bir sonraki hazırlıkta daha dikkatli değerlendirmeyi öğrenir. Aynı iteme arka arkaya + basarken **beşinci ve sonraki denemelerin başarı ihtimali +0,4 yüzde puan artar**.","effect_text":"Aynı iteme arka arkaya + basarken beşinci ve sonraki denemelerin başarı ihtimali +0,4 yüzde puan artar.","rarity":"rare","effect":{"metric":"upgrade_success_probability","operation":"add_probability","value":0.004,"unit":"fraction","parameters":{"bonus_kind":"conditional"}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve upgrade serisinde işlem öncesi en az 4 tamamlanmış deneme vardır."]},{"content_id":"blacksmith_general_008","role_id":"smith","profession":"blacksmith","ordinal":8,"title":"Başarısızlığın İzlerini Okumak","subtitle":"Sonuç vermeyen bir çalışmadan bilgi çıkarabilmek.","paragraph":"Başarısız geliştirmelere ait gözlemler, Demirciye yapılan işlemin nerede zorlandığını değerlendirmeyi öğretir. Aynı ekipmanı yeniden ele alırken önceki denemenin izlerinden yararlanır. Aynı itemdeki serinin önceki + basışı başarısızsa **bir sonraki denemenin başarı ihtimali +0,2 yüzde puan artar**.","effect_text":"Aynı itemdeki serinin önceki + basışı başarısızsa bir sonraki denemenin başarı ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"upgrade_success_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional"}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve upgrade serisinin son tamamlanan denemesi başarısızdır."]},{"content_id":"blacksmith_general_009","role_id":"smith","profession":"blacksmith","ordinal":9,"title":"İki Hatanın Ardındaki Bilgi","subtitle":"Tekrarlanan başarısızlıkta ortak işareti bulabilmek.","paragraph":"Papirüs, peş peşe sonuç vermeyen çalışmaların kayıtlarını yan yana getirir. Demirci, aynı ekipmanda tekrarlanan sorunları karşılaştırmayı ve sonraki hazırlığını bu bilgiyle düzenlemeyi öğrenir. Aynı itemde arka arkaya iki + basışı başarısız olduysa **bir sonraki denemenin başarı ihtimali +0,4 yüzde puan artar**.","effect_text":"Aynı itemde arka arkaya iki + basışı başarısız olduysa bir sonraki denemenin başarı ihtimali +0,4 yüzde puan artar.","rarity":"unique","effect":{"metric":"upgrade_success_probability","operation":"add_probability","value":0.004,"unit":"fraction","parameters":{"bonus_kind":"conditional"}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve upgrade serisinin son iki tamamlanan denemesi başarısızdır."]},{"content_id":"blacksmith_general_010","role_id":"smith","profession":"blacksmith","ordinal":10,"title":"Safirin İçindeki Işık","subtitle":"Taşın işçiliğinde kaliteyi belirleyen ayrıntıları tanımak.","paragraph":"Papirüs, safir yüzeyindeki ışık ve yerleşim izlerini karşılaştırır. Demirci, safir uygulamasının hazırlığını daha dikkatli değerlendirecek bir göz kazanır. Safir basarken **%95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar**.","effect_text":"Safir basarken %95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"sapphire_quality_at_least_95_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"general","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Geçerli bir safir basma işlemi."]},{"content_id":"blacksmith_general_011","role_id":"smith","profession":"blacksmith","ordinal":11,"title":"Safirde Ardışık İşçilik","subtitle":"Aynı ekipmandaki taş uygulamalarını birlikte okuyabilmek.","paragraph":"Arka arkaya yapılan safir uygulamalarının notları, her çalışmadan edinilen gözlemin bir sonrakine nasıl taşındığını anlatır. Demirci, aynı ekipmana alıştıkça hazırlığını daha bilinçli yapmayı öğrenir. Aynı iteme arka arkaya safir basarken üçüncü ve sonraki uygulamalarda **%95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar**.","effect_text":"Aynı iteme arka arkaya safir basarken üçüncü ve sonraki uygulamalarda %95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"sapphire_quality_at_least_95_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve sapphire serisinde işlem öncesi en az 2 tamamlanmış basış vardır."]},{"content_id":"blacksmith_general_012","role_id":"smith","profession":"blacksmith","ordinal":12,"title":"Safirde Beşinci Uygulama","subtitle":"Uzayan taş işçiliğinde biriken deneyimi değerlendirmek.","paragraph":"Papirüs, aynı ekipmanda sürdürülen safir çalışmalarının ayrıntılı kayıtlarını içerir. Demirci, tekrarlar boyunca fark ettiği küçük işaretleri sonraki uygulamada kullanmayı öğrenir. Aynı iteme arka arkaya safir basarken beşinci ve sonraki uygulamalarda **%95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar**.","effect_text":"Aynı iteme arka arkaya safir basarken beşinci ve sonraki uygulamalarda %95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar.","rarity":"rare","effect":{"metric":"sapphire_quality_at_least_95_probability","operation":"add_probability","value":0.004,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve sapphire serisinde işlem öncesi en az 4 tamamlanmış basış vardır."]},{"content_id":"blacksmith_general_013","role_id":"smith","profession":"blacksmith","ordinal":13,"title":"Soluk Safirin Öğrettikleri","subtitle":"Beklenen kaliteye ulaşmayan işçilikten ders çıkarabilmek.","paragraph":"Düşük kaliteyle sonuçlanan safir uygulamalarının yanına yazılmış notlar, Demirciye sonucu dikkatle incelemeyi öğretir. Aynı ekipmandaki sonraki safiri bu gözlemlerden yararlanarak hazırlar. Aynı itemdeki serinin önceki safir sonucu %95 altındaysa sonraki basışta **%95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar**.","effect_text":"Aynı itemdeki serinin önceki safir sonucu %95 altındaysa sonraki basışta %95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"sapphire_quality_at_least_95_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve sapphire serisinin son tamamlanan basışının kalite sonucu 0.95 altındadır."]},{"content_id":"blacksmith_general_014","role_id":"smith","profession":"blacksmith","ordinal":14,"title":"Safirde Tekrarlanan Kusuru Okumak","subtitle":"İki yetersiz sonuç arasındaki ortak izi görebilmek.","paragraph":"Papirüs, peş peşe düşük kalite veren safir çalışmalarını karşılaştırır. Demirci, tekrarlanan eksikliği değerlendirmeyi ve sonraki uygulamasını bu bilgiyle düzenlemeyi öğrenir. Aynı itemde arka arkaya iki safir sonucu %95 altındaysa sonraki basışta **%95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar**.","effect_text":"Aynı itemde arka arkaya iki safir sonucu %95 altındaysa sonraki basışta %95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar.","rarity":"very_rare","effect":{"metric":"sapphire_quality_at_least_95_probability","operation":"add_probability","value":0.004,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve sapphire serisinin son iki tamamlanan basışının kalite sonucu 0.95 altındadır."]},{"content_id":"blacksmith_general_015","role_id":"smith","profession":"blacksmith","ordinal":15,"title":"Gelişmiş Yüzeyde Safir İşçiliği","subtitle":"Geliştirilmiş ekipmanın taş yuvasını anlayabilmek.","paragraph":"Orta kademeli ekipmanların safir yuvalarına ait çizimler, yüzey ile taşın yerleşimi arasındaki ilişkiyi gösterir. Demirci, geliştirilmiş parçaya uygun hazırlığı öğrenir. Mevcut seviyesi +5–+8 olan iteme safir basarken **%95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar**.","effect_text":"Mevcut seviyesi +5–+8 olan iteme safir basarken %95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar.","rarity":"rare","effect":{"metric":"sapphire_quality_at_least_95_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","İşlem öncesindeki mevcut item seviyesi +5 ile +8 arasındadır."]},{"content_id":"blacksmith_general_016","role_id":"smith","profession":"blacksmith","ordinal":16,"title":"Usta Ekipmana Safir Yerleştirmek","subtitle":"Yüksek kademeli işçiliğin taşla ilişkisini kavramak.","paragraph":"Papirüs, yüksek seviyeli ekipmanlarda yapılan safir uygulamalarını inceler. Demirci, hassas biçimde işlenmiş bir yuvayı değerlendirmeyi ve taşın hazırlığını buna göre düzenlemeyi öğrenir. Mevcut seviyesi +9 veya üzeri olan iteme safir basarken **%95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar**.","effect_text":"Mevcut seviyesi +9 veya üzeri olan iteme safir basarken %95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar.","rarity":"very_rare","effect":{"metric":"sapphire_quality_at_least_95_probability","operation":"add_probability","value":0.004,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","İşlem öncesindeki mevcut item seviyesi en az +9dur."]},{"content_id":"blacksmith_general_017","role_id":"smith","profession":"blacksmith","ordinal":17,"title":"Zümrüdün Yanında Safir","subtitle":"Yerleşmiş kaliteli bir taştan yeni işçilik için bilgi edinmek.","paragraph":"Aynı ekipmanda bulunan safir ve zümrüt yuvalarının çizimleri, Demirciye tamamlanmış bir uygulamayı referans almayı öğretir. Takılı kaliteli zümrüdün işçiliğinden öğrendiklerini safir hazırlığına taşır. Üzerinde %95 veya üzeri kaliteli zümrüt takılı olan iteme safir basarken **%95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar**.","effect_text":"Üzerinde %95 veya üzeri kaliteli zümrüt takılı olan iteme safir basarken %95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar.","rarity":"rare","effect":{"metric":"sapphire_quality_at_least_95_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","İşlem öncesinde aynı fiziksel itemde en az bir adet %95 veya üzeri kaliteli zümrüt takılıdır."]},{"content_id":"blacksmith_general_018","role_id":"smith","profession":"blacksmith","ordinal":18,"title":"Zümrüdün Derinliğini Okumak","subtitle":"Taşın yüzeyindeki ince ayrıntılardan kaliteyi anlamak.","paragraph":"Papirüs, zümrüt uygulamalarında görülen yüzey ve yerleşim özelliklerini anlatır. Demirci, yüksek kaliteli bir sonuç için hazırlık sırasında nelere dikkat edeceğini öğrenir. Zümrüt basarken **%95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar**.","effect_text":"Zümrüt basarken %95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"emerald_quality_at_least_95_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"general","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Geçerli bir zümrüt basma işlemi."]},{"content_id":"blacksmith_general_019","role_id":"smith","profession":"blacksmith","ordinal":19,"title":"Zümrütte Ardışık İşçilik","subtitle":"Tekrar edilen uygulamalardan düzenli bilgi çıkarabilmek.","paragraph":"Aynı ekipmana yapılan zümrüt uygulamalarının kayıtları, her denemenin sonraki hazırlığa nasıl katkı verdiğini gösterir. Demirci, parçayı tanıdıkça işçiliğini daha dikkatli düzenlemeyi öğrenir. Aynı iteme arka arkaya zümrüt basarken üçüncü ve sonraki uygulamalarda **%95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar**.","effect_text":"Aynı iteme arka arkaya zümrüt basarken üçüncü ve sonraki uygulamalarda %95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar.","rarity":"common","effect":{"metric":"emerald_quality_at_least_95_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve emerald serisinde işlem öncesi en az 2 tamamlanmış basış vardır."]},{"content_id":"blacksmith_general_020","role_id":"smith","profession":"blacksmith","ordinal":20,"title":"Zümrütte Beşinci Uygulama","subtitle":"Biriken gözlemleri hassas bir işçiliğe dönüştürmek.","paragraph":"Papirüs, uzun süren zümrüt çalışmalarında fark edilen küçük ayrıntıları bir araya getirir. Demirci, aynı ekipmanda edindiği deneyimi sonraki taşın hazırlanışında kullanmayı öğrenir. Aynı iteme arka arkaya zümrüt basarken beşinci ve sonraki uygulamalarda **%95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar**.","effect_text":"Aynı iteme arka arkaya zümrüt basarken beşinci ve sonraki uygulamalarda %95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar.","rarity":"rare","effect":{"metric":"emerald_quality_at_least_95_probability","operation":"add_probability","value":0.004,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve emerald serisinde işlem öncesi en az 4 tamamlanmış basış vardır."]},{"content_id":"blacksmith_general_021","role_id":"smith","profession":"blacksmith","ordinal":21,"title":"Sönük Zümrüdün Öğrettikleri","subtitle":"Düşük kaliteli sonucun bıraktığı izi değerlendirmek.","paragraph":"Beklenen kaliteye ulaşmayan zümrüt uygulamalarına ait notlar, Demirciye sonucu okumayı öğretir. Bu bilgi, aynı ekipmana bir sonraki zümrüdü hazırlarken yaptığı değerlendirmeyi geliştirir. Aynı itemdeki serinin önceki zümrüt sonucu %95 altındaysa sonraki basışta **%95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar**.","effect_text":"Aynı itemdeki serinin önceki zümrüt sonucu %95 altındaysa sonraki basışta %95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar.","rarity":"rare","effect":{"metric":"emerald_quality_at_least_95_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve emerald serisinin son tamamlanan basışının kalite sonucu 0.95 altındadır."]},{"content_id":"blacksmith_general_022","role_id":"smith","profession":"blacksmith","ordinal":22,"title":"Zümrütte Tekrarlanan Kusuru Okumak","subtitle":"Peş peşe gelen yetersiz sonuçları karşılaştırabilmek.","paragraph":"Papirüs, art arda düşük kaliteyle sonuçlanan zümrüt uygulamalarını birlikte ele alır. Demirci, ortak işaretleri bulmayı ve sonraki işçiliğini bu gözleme göre hazırlamayı öğrenir. Aynı itemde arka arkaya iki zümrüt sonucu %95 altındaysa sonraki basışta **%95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar**.","effect_text":"Aynı itemde arka arkaya iki zümrüt sonucu %95 altındaysa sonraki basışta %95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar.","rarity":"very_rare","effect":{"metric":"emerald_quality_at_least_95_probability","operation":"add_probability","value":0.004,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","Aynı fiziksel item ve emerald serisinin son iki tamamlanan basışının kalite sonucu 0.95 altındadır."]},{"content_id":"blacksmith_general_023","role_id":"smith","profession":"blacksmith","ordinal":23,"title":"Gelişmiş Yüzeyde Zümrüt İşçiliği","subtitle":"Orta kademeli ekipmana uygun taş hazırlığını öğrenmek.","paragraph":"Geliştirilmiş ekipmanlardaki zümrüt yuvalarının çizimleri, yüzeyin işçilik geçmişini gösterir. Demirci, taş uygulamasını bu geçmişi dikkate alarak hazırlama becerisi kazanır. Mevcut seviyesi +5–+8 olan iteme zümrüt basarken **%95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar**.","effect_text":"Mevcut seviyesi +5–+8 olan iteme zümrüt basarken %95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar.","rarity":"rare","effect":{"metric":"emerald_quality_at_least_95_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","İşlem öncesindeki mevcut item seviyesi +5 ile +8 arasındadır."]},{"content_id":"blacksmith_general_024","role_id":"smith","profession":"blacksmith","ordinal":24,"title":"Usta Ekipmana Zümrüt Yerleştirmek","subtitle":"Yüksek işçilik isteyen bir parçayı taşla tamamlayabilmek.","paragraph":"Papirüs, yüksek seviyeli ekipmanlarda zümrüt yerleşiminin inceliklerini anlatır. Demirci, hassas yüzeyleri değerlendirmeyi ve uygulama öncesindeki hazırlığını buna göre yapmayı öğrenir. Mevcut seviyesi +9 veya üzeri olan iteme zümrüt basarken **%95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar**.","effect_text":"Mevcut seviyesi +9 veya üzeri olan iteme zümrüt basarken %95 ve üzeri kalite elde etme ihtimali +0,4 yüzde puan artar.","rarity":"very_rare","effect":{"metric":"emerald_quality_at_least_95_probability","operation":"add_probability","value":0.004,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","İşlem öncesindeki mevcut item seviyesi en az +9dur."]},{"content_id":"blacksmith_general_025","role_id":"smith","profession":"blacksmith","ordinal":25,"title":"Safirin Yanında Zümrüt","subtitle":"Kaliteli bir uygulamayı yeni işçiliğin rehberi yapmak.","paragraph":"Birlikte kullanılan taş yuvalarına ait notlar, Demirciye takılı safirin işçiliğinden yararlanmayı öğretir. Ekipmandaki kaliteli uygulamayı inceleyerek zümrüt hazırlığına aktarabileceği bilgi edinir. Üzerinde %95 veya üzeri kaliteli safir takılı olan iteme zümrüt basarken **%95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar**.","effect_text":"Üzerinde %95 veya üzeri kaliteli safir takılı olan iteme zümrüt basarken %95 ve üzeri kalite elde etme ihtimali +0,2 yüzde puan artar.","rarity":"rare","effect":{"metric":"emerald_quality_at_least_95_probability","operation":"add_probability","value":0.002,"unit":"fraction","parameters":{"bonus_kind":"conditional","quality_threshold":0.95}},"conditions":["Papirüs Demirci tarafından öğrenilmiş olmalıdır.","Bütün + basılabilen item modellerinde, ilgili işlemin desteklendiği ekipmanlarda geçerlidir.","Koşullar işlem başlamadan önce değerlendirilir.","Aynı işlemde öğrenilmiş genel bonus ile uygun koşullu bonusların yalnız en yükseği uygulanır.","İşlem öncesinde aynı fiziksel itemde en az bir adet %95 veya üzeri kaliteli safir takılıdır."]}]$catalog$::jsonb)as x(content_id text,role_id text,profession text,ordinal smallint,title text,subtitle text,paragraph text,effect_text text,rarity text,effect jsonb,conditions jsonb);

create view ludus_staff_private.learned_papyrus_v288 with(security_invoker=true) as
 select k.owner_id,c.content_id,c.role_id,c.profession,c.ordinal,c.effect,c.conditions,c.title,k.learned_at,c.runtime_status,c.runtime_reason,c.runtime_note
 from ludus_staff_private.knowledge_v288 k join ludus_staff_private.papyrus_catalog_v288 c using(content_id) where c.runtime_status='active';
create function ludus_staff_private.catalog_effects_v288(p_owner uuid,p_role text default null)
returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('content_id',content_id,'role',role_id,'effect',effect,'conditions',conditions,'title',title,'learned_at',learned_at) order by role_id,ordinal),'[]'::jsonb)
 from ludus_staff_private.learned_papyrus_v288 where owner_id=p_owner and (p_role is null or role_id=p_role)
$$;
create function ludus_staff_private.catalog_rows_v288(p_owner uuid,p_role text default null)
returns table(ordinal integer,entry jsonb) language sql stable set search_path='' as $$
 select c.ordinal::integer,jsonb_build_object('id',c.content_id,'content_id',c.content_id,'role',c.role_id,'profession',c.profession,'ordinal',c.ordinal,
 'title',c.title,'subtitle',c.subtitle,'paragraph',c.paragraph,'effect_text',c.effect_text,'rarity',c.rarity,'effect',c.effect,'conditions',c.conditions,'runtime_status',c.runtime_status,'runtime_binding_status',c.runtime_status,'runtime_reason',c.runtime_reason,'runtime_note',c.runtime_note,
 'effects',jsonb_build_array(jsonb_build_object('key',coalesce(c.effect->>'metric',c.effect->>'stat',c.content_id),'label',c.effect_text,'target',c.role_id,
 'value',c.effect->'value','unit',c.effect->'unit','operation',c.effect->'operation','percent',case when c.effect->>'unit'='fraction' then (c.effect->>'value')::numeric*100 else null end,'conditions',c.conditions)),
 'owned_quantity',coalesce(h.quantity,0),'quantity',coalesce(h.quantity,0),'read_at',k.learned_at,'learned',k.content_id is not null,
 'acquired',k.content_id is not null or coalesce(h.quantity,0)>0,'available',k.content_id is null and coalesce(h.quantity,0)>0,
 'finder',d.finder_ludus,'found_at',d.found_at)
 from ludus_staff_private.papyrus_catalog_v288 c
 left join ludus_staff_private.holdings_v288 h on h.owner_id=p_owner and h.content_id=c.content_id
 left join ludus_staff_private.knowledge_v288 k on k.owner_id=p_owner and k.content_id=c.content_id
 left join ludus_staff_private.unique_mints_v288 d on d.content_id=c.content_id
 where p_role is null or c.role_id=p_role
$$;
create function ludus_staff_private.catalog_state_v288(p_role text default 'trainer')
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare u uuid:=auth.uid();staff jsonb;papers jsonb;
begin
 if u is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'Giriş gerekiyor.' using errcode='42501';end if;
 if not exists(select 1 from public.ludus_accounts where user_id=u)then raise exception 'Ludus bulunamadı.';end if;
 if p_role is null or not exists(select 1 from ludus_staff_private.roles_v284 where id=p_role)then raise exception 'Çalışan geçersiz.';end if;
 with counts as(
 select c.role_id,count(*)filter(where k.content_id is not null or coalesce(h.quantity,0)>0) collected,
 count(k.content_id) learned,coalesce(sum(h.quantity),0) unread_quantity,
 count(*)filter(where k.content_id is null and coalesce(h.quantity,0)>0) readable
 from ludus_staff_private.papyrus_catalog_v288 c
 left join ludus_staff_private.holdings_v288 h on h.owner_id=u and h.content_id=c.content_id
 left join ludus_staff_private.knowledge_v288 k on k.owner_id=u and k.content_id=c.content_id group by c.role_id)
 select jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'title',r.title,'total',25,'collected',n.collected,'read',n.learned,
 'overall',n.collected*4,'learned_percent',n.learned*4,'unread_quantity',n.unread_quantity,'readable',n.readable,
 'bonuses',ludus_staff_private.catalog_effects_v288(u,r.id),'legacy_bonuses',ludus_staff_private.bonuses_v284(u,r.id),
 'legacy_total',500,'legacy_collected',(select count(*)from ludus_staff_private.papers_v286(u)p where p.role=r.id),
 'legacy_read',(select count(*)from ludus_staff_private.papers_v286(u)p where p.role=r.id and p.read_at is not null),
 'legacy_unique_read',(select count(*)from ludus_staff_private.papers_v286(u)p where p.role=r.id and p.read_at is not null and p.unique_id is not null))order by r.sort_order)
 into staff from ludus_staff_private.roles_v284 r join counts n on n.role_id=r.id;
 select jsonb_agg(entry order by ordinal)into papers from ludus_staff_private.catalog_rows_v288(u,p_role);
 return jsonb_build_object('user_id',u,'role',p_role,'staff',staff,'papyri',papers,'paper_count',25,'catalog_version',288);
end;$$;
create function ludus_staff_private.catalog_read_v288(p_content_id text,p_request uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();r text;receipt text;replayed boolean:=false;
begin
 if u is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false)then raise exception 'Giriş gerekiyor.' using errcode='42501';end if;
 if p_request is null or p_content_id is null then raise exception 'Papirüs ve işlem bilgisi gerekiyor.';end if;
 perform 1 from public.ludus_accounts where user_id=u for update;if not found then raise exception 'Ludus bulunamadı.';end if;
 select role_id into r from ludus_staff_private.papyrus_catalog_v288 where content_id=p_content_id;if not found then raise exception 'Papirüs bulunamadı.';end if;
 select content_id into receipt from ludus_staff_private.read_receipts_v288 where owner_id=u and request_id=p_request;
 if found then
  if receipt<>p_content_id then raise exception 'İşlem kimliği farklı bir papirüs için kullanılmış.';end if;replayed:=true;
 else
  if exists(select 1 from ludus_staff_private.knowledge_v288 where owner_id=u and content_id=p_content_id)then raise exception 'Bu bilgi zaten öğrenildi.';end if;
  update ludus_staff_private.holdings_v288 set quantity=quantity-1 where owner_id=u and content_id=p_content_id and quantity>0;
  if not found then raise exception 'Bu papirüs kasanda yok.';end if;
  insert into ludus_staff_private.knowledge_v288(owner_id,content_id)values(u,p_content_id);
  insert into ludus_staff_private.read_receipts_v288(owner_id,request_id,content_id)values(u,p_request,p_content_id);
 end if;
 return ludus_staff_private.catalog_state_v288(r)||jsonb_build_object('reading',jsonb_build_object('content_id',p_content_id,'replayed',replayed));
end;$$;
create function public.ludus_papyrus_state_v288(p_role text default 'trainer')returns jsonb language sql stable security invoker set search_path='' as $$select ludus_staff_private.catalog_state_v288(p_role)$$;
create function public.ludus_papyrus_read_v288(p_content_id text,p_request uuid)returns jsonb language sql security invoker set search_path='' as $$select ludus_staff_private.catalog_read_v288(p_content_id,p_request)$$;

-- One unbiased roll on a 10-million grid: 125000 common,25000 rare,2500 very rare,25 unique.
create function ludus_staff_private.rarity_v288(p_roll integer)returns text language sql immutable set search_path='' as $$
 select case when p_roll<0 or p_roll>=10000000 then null when p_roll<25 then 'unique' when p_roll<2525 then 'very_rare' when p_roll<27525 then 'rare' when p_roll<152525 then 'common' end
$$;
create function ludus_staff_private.roll_v288()returns integer language sql volatile set search_path='' as $$select floor(random()*10000000)::integer$$;
-- Owner lock is always acquired before the global unique lock (shared with grants).
create function ludus_staff_private.mint_v288(p_owner uuid,p_content_id text,p_source text)returns jsonb
language plpgsql set search_path='' as $$
declare c ludus_staff_private.papyrus_catalog_v288;d ludus_staff_private.unique_mints_v288;finder text;
begin
 select * into c from ludus_staff_private.papyrus_catalog_v288 where content_id=p_content_id;if not found then raise exception 'Papirüs bulunamadı.';end if;
 if c.rarity='unique' then
  perform pg_advisory_xact_lock(288150);
  select coalesce(nullif(ludus_name,''),username,'Ludus')into finder from public.ludus_accounts where user_id=p_owner;
  insert into ludus_staff_private.unique_mints_v288(content_id,first_owner_id,finder_ludus,source_key)values(p_content_id,p_owner,finder,p_source)on conflict do nothing returning * into d;
  if not found then return null;end if;
 end if;
 insert into ludus_staff_private.holdings_v288(owner_id,content_id,quantity)values(p_owner,p_content_id,1)
 on conflict(owner_id,content_id)do update set quantity=ludus_staff_private.holdings_v288.quantity+1;
 return jsonb_build_object('content_id',c.content_id,'role',c.role_id,'title',c.title,'rarity',c.rarity,'role_title',(select title from ludus_staff_private.roles_v284 where id=c.role_id),
 'quantity',1,'finder',d.finder_ludus,'found_at',d.found_at);
end;$$;
create or replace function ludus_staff_private.award_v285(p_owner uuid,p_source text)returns jsonb
language plpgsql security definer set search_path='' as $$
declare selected_rarity text;chosen text;paper jsonb;answer jsonb:='[]';
begin
 if p_owner is null or p_source is null then raise exception 'Ganimet kaydı eksik.';end if;
 perform 1 from public.ludus_accounts where user_id=p_owner for update;if not found then return answer;end if;
 if exists(select 1 from ludus_bot_private.members_v233 where user_id=p_owner)or exists(select 1 from ludus_staff_private.loot_exclusions_v288 where owner_id=p_owner)then return answer;end if;
 -- Reuse the existing source receipt namespace: old settled matches never reroll.
 insert into ludus_staff_private.loot_receipts_v285(source_key,owner_id)values(p_source,p_owner)on conflict do nothing;
 if not found then return(select papyri from ludus_staff_private.loot_receipts_v285 where source_key=p_source and owner_id=p_owner);end if;
 selected_rarity:=ludus_staff_private.rarity_v288(ludus_staff_private.roll_v288());
 if selected_rarity='unique' then perform pg_advisory_xact_lock(288150);end if;
 select content_id into chosen from ludus_staff_private.papyrus_catalog_v288 c where c.rarity=selected_rarity
 and(c.rarity<>'unique' or not exists(select 1 from ludus_staff_private.unique_mints_v288 m where m.content_id=c.content_id))order by random()limit 1;
 if found then paper:=ludus_staff_private.mint_v288(p_owner,chosen,p_source);if paper is not null then answer:=jsonb_build_array(paper);end if;end if;
 update ludus_staff_private.loot_receipts_v285 set papyri=answer where source_key=p_source and owner_id=p_owner;return answer;
end;$$;
create or replace function ludus_staff_private.battle_loot_v285()returns trigger language plpgsql security definer set search_path='' as $$
begin
 if old.finished_at is null and new.finished_at is not null and new.won is not null
 and new.finished_at>=new.started_at+interval '10 seconds' and new.finished_at<=new.started_at+interval '2 hours'
 and exists(select 1 from ludus_staff_private.loot_settings_v288 where all_matches or new.mode=any(allowed_match_types))then
  new.reward:=coalesce(new.reward,'{}')||jsonb_build_object('papyri',ludus_staff_private.award_v285(new.owner_id,'battle:'||new.id::text));
 end if;return new;
end;$$;
create or replace function ludus_staff_private.match_loot_v285()returns trigger language plpgsql security definer set search_path='' as $$
declare p jsonb;team text;
begin
 if old.status<>'playing' or new.status<>'finished' or new.winner is null or new.starts_at is null
 or clock_timestamp()<new.starts_at+interval '10 seconds' or clock_timestamp()>new.starts_at+interval '2 hours'
 or not exists(select 1 from ludus_staff_private.loot_settings_v288 where all_matches or new.venue=any(allowed_match_types))then return new;end if;
 if not exists(select 1 from jsonb_array_elements(new.players)f where f->>'owner'=new.winner::text and coalesce((f->>'hp')::numeric,0)>0 and not coalesce((f->>'left')::boolean,false))then return new;end if;
 select f->>'ranked_team' into team from jsonb_array_elements(new.players)f where f->>'owner'=new.winner::text;
 if new.venue='ranked' and(team is null or jsonb_array_length(new.players)<>10 or(select count(distinct f->>'owner')from jsonb_array_elements(new.players)f)<>10
 or(select count(*)from jsonb_array_elements(new.players)f where f->>'ranked_team'='a')<>5 or(select count(*)from jsonb_array_elements(new.players)f where f->>'ranked_team'='b')<>5)then return new;end if;
 if not exists(select 1 from jsonb_array_elements(new.players)f where coalesce((f->>'hp')::numeric,0)<=0 and not coalesce((f->>'left')::boolean,false)
 and case when new.venue='ranked' then f->>'ranked_team'<>team else f->>'owner'<>new.winner::text end)then return new;end if;
 new.papyri_eligible_v285:='{}';
 for p in select f from jsonb_array_elements(new.players)f where not coalesce((f->>'left')::boolean,false) order by f->>'owner' loop
  new.papyri_eligible_v285:=array_append(new.papyri_eligible_v285,(p->>'owner')::uuid);
 end loop;return new;
end;$$;

-- Prepared grant is NOT applied by this migration; deployment explicitly invokes it once.
create function ludus_staff_private.apply_grant_v288(p_request uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare g ludus_staff_private.grant_requests_v288;candidate text;chosen text;given text[]:='{}';paper jsonb;items jsonb:='[]';replacements jsonb:='[]';before_learned integer;after_learned integer;
begin
 select * into g from ludus_staff_private.grant_requests_v288 where request_id=p_request;if not found then raise exception 'Onaylı ekleme planı bulunamadı.';end if;
 perform 1 from public.ludus_accounts where user_id=g.owner_id and username=g.expected_username and ludus_name=g.expected_ludus_name for update;
 if not found then raise exception 'Ekleme hedefi doğrulanamadı.';end if;
 select * into g from ludus_staff_private.grant_requests_v288 where request_id=p_request for update;if g.receipt is not null then return g.receipt;end if;
 if (select count(distinct x)from jsonb_array_elements_text(g.planned_ids)x)<>90 or exists(select 1 from jsonb_array_elements_text(g.planned_ids)x where not exists(select 1 from ludus_staff_private.papyrus_catalog_v288 c where c.content_id=x))then raise exception 'Plan geçersiz.';end if;
 select count(*)into before_learned from ludus_staff_private.knowledge_v288 where owner_id=g.owner_id;
 perform pg_advisory_xact_lock(288150);
 for candidate in select jsonb_array_elements_text(g.planned_ids) loop
  chosen:=candidate;
  if exists(select 1 from ludus_staff_private.unique_mints_v288 where content_id=chosen)then
   select c.content_id into chosen from ludus_staff_private.papyrus_catalog_v288 c
   where not g.planned_ids ? c.content_id and not c.content_id=any(given)
   and not exists(select 1 from ludus_staff_private.unique_mints_v288 m where m.content_id=c.content_id)order by random()limit 1;
   if chosen is null then raise exception 'Ekleme için yeterli farklı bilgi kalmadı.';end if;
   replacements:=replacements||jsonb_build_array(jsonb_build_object('original',candidate,'replacement',chosen));
  end if;
  paper:=ludus_staff_private.mint_v288(g.owner_id,chosen,'grant:'||p_request::text);if paper is null then raise exception 'Eşsiz bilgi üretilemedi.';end if;
  items:=items||jsonb_build_array(paper);given:=array_append(given,chosen);
 end loop;
 select count(*)into after_learned from ludus_staff_private.knowledge_v288 where owner_id=g.owner_id;
 if jsonb_array_length(items)<>90 or before_learned<>after_learned then raise exception 'Ekleme doğrulaması başarısız.';end if;
 update ludus_staff_private.grant_requests_v288 set applied_at=clock_timestamp(),receipt=jsonb_build_object('request_id',p_request,'owner_id',g.owner_id,'quantity',90,'auto_learn',false,'items',items,'replacements',replacements,'learned_before',before_learned,'learned_after',after_learned)where request_id=p_request returning receipt into g.receipt;
 return g.receipt;
end;$$;

-- The existing chest API gains new copies without modifying the legacy archive view.
create or replace function ludus_staff_private.vault_rows_v286(p_owner uuid)
returns table(category text,key text,sort_order integer,entry jsonb)
language sql stable security definer set search_path='' as $$
 select 'money','denarius',0,jsonb_build_object('type','money','name','Denarius','quantity',a.gold)
 from public.ludus_accounts a where a.user_id=p_owner
 union all
 select 'stone','diamond',1,jsonb_build_object('type','stone','family','diamond','stone_id',1,'quantity',a.diamonds)
 from public.ludus_accounts a where a.user_id=p_owner and a.diamonds>0
 union all
 select 'stone',s.family||':'||s.stone_id,2,jsonb_build_object('type','stone','family',s.family,'stone_id',s.stone_id,'quantity',s.quantity)
 from public.ludus_stones s where s.owner_id=p_owner and s.quantity>0
 union all
 select 'papyrus',p.role||':'||coalesce(p.unique_id,p.lesson::text),3,
  to_jsonb(p)||jsonb_build_object('type','papyrus','name',p.title,'quantity',1,'role_name',r.name,'role_title',r.title)
 from ludus_staff_private.papers_v286(p_owner) p join ludus_staff_private.roles_v284 r on r.id=p.role where p.read_at is null
 union all
 select 'resource',s.sku,4,jsonb_build_object('type','resource','sku',s.sku,'name',r.name,'stage',r.stage,'quantity',s.quantity,'retired',not r.active)
 from ludus_supply_private.stock s join ludus_supply_private.resources r using(sku) where s.owner_id=p_owner and s.quantity>0
 union all
 select 'food',s.sku,5,jsonb_build_object('type','food','sku',s.sku,'name',c.name,'quantity',s.quantity,'retired',c.retired)
 from public.ludus_food_stock s join public.ludus_food_catalog c using(sku) where s.owner_id=p_owner and s.quantity>0
 union all
 select 'equipment',i.id::text,6,jsonb_build_object('type','equipment','id',i.id,'kind',i.kind,'model',i.model,
  'enhancement',i.enhancement,'base_stats',i.base_stats,'natural_stats',i.natural_stats,'natural_percentages',i.natural_percentages,
  'sapphires',i.sapphires,'emeralds',i.emeralds,'rubies',i.rubies,'quantity',1,'equipped_by',i.equipped_by,'equipped_name',g.name,
  'equipped_slot',i.equipped_slot,'in_battle',i.locked_battle_id is not null,'on_market',i.market_listing_id is not null,
  'in_clan_roster',i.clan_roster_id is not null)
 from public.ludus_items i left join public.ludus_gladiators g on g.id=i.equipped_by and g.owner_id=p_owner
 where i.owner_id=p_owner and i.clan_vault_id is null
 union all
 select 'papyrus','catalog:'||(p.entry->>'content_id'),3,p.entry||jsonb_build_object('type','papyrus','name',p.entry->>'title','role_name',r.name,'role_title',r.title)
 from ludus_staff_private.catalog_rows_v288(p_owner,null)p join ludus_staff_private.roles_v284 r on r.id=p.entry->>'role'
 where (p.entry->>'owned_quantity')::integer>0
;
$$;
revoke all on function ludus_staff_private.vault_rows_v286(uuid) from public,anon,authenticated;



-- Closed-by-default tables and functions. Only owner-validating RPCs are callable.
do $$declare t text;begin
 foreach t in array array['papyrus_catalog_v288','holdings_v288','knowledge_v288','unique_mints_v288','read_receipts_v288','grant_requests_v288','loot_settings_v288','loot_exclusions_v288']loop
  execute format('alter table ludus_staff_private.%I enable row level security',t);
  execute format('revoke all on ludus_staff_private.%I from public,anon,authenticated',t);
 end loop;
end;$$;
revoke all on ludus_staff_private.learned_papyrus_v288 from public,anon,authenticated;
revoke all on function ludus_staff_private.catalog_effects_v288(uuid,text),ludus_staff_private.catalog_rows_v288(uuid,text),ludus_staff_private.catalog_state_v288(text),ludus_staff_private.catalog_read_v288(text,uuid),ludus_staff_private.rarity_v288(integer),ludus_staff_private.roll_v288(),ludus_staff_private.mint_v288(uuid,text,text),ludus_staff_private.apply_grant_v288(uuid),public.ludus_papyrus_state_v288(text),public.ludus_papyrus_read_v288(text,uuid) from public,anon,authenticated;
grant execute on function ludus_staff_private.catalog_state_v288(text),ludus_staff_private.catalog_read_v288(text,uuid),public.ludus_papyrus_state_v288(text),public.ludus_papyrus_read_v288(text,uuid)to authenticated;
